export const editorialConceptsWave6=[
{
 id:'neutron-ung-suat-con-lai-trong-duong-ray',category:'khainiem',title:'Đo lực còn nằm trong đường ray sau khi đoàn tàu đã đi',summary:'Nhiễu xạ neutron đọc biến dạng mạng tinh thể để khảo sát ứng suất dư. Một thanh thép đứng yên vẫn có thể giữ lịch sử gia công và tải trọng bên trong.',tags:['Ứng suất dư','Neutron','Đường ray'],image:'/assets/library/photos/elements/Fe.jpg',imageAlt:'Iron minh họa nguyên tố nền của thép; không phải mẫu đường ray được đo',sections:[
 ['Một thanh ray không còn chịu tải ngoài vẫn chưa hết ứng suất',`Báo cáo NIST về các lát đường ray được mài theo những lịch trình khác nhau dùng nhiễu xạ neutron để lập bản đồ vùng đầu ray. Nhóm thấy các miền chịu kéo và nén còn lại dưới bề mặt, dù mẫu đã được đưa ra khỏi điều kiện đoàn tàu đang chạy. Lịch sử tiếp xúc và gia công đã để dấu trong vật liệu.

Trong báo cáo nghiên cứu năm 2004, NIST tiếp tục đo trên một đoạn ray nguyên vẹn để khảo sát phân bố ba chiều. Cắt lát có thể giải phóng một phần ứng suất, nên đo vật còn nguyên bổ sung thông tin mà lát cắt không giữ đầy đủ. Đây là lý do cách chuẩn bị mẫu thuộc về câu hỏi vật lý, không chỉ là bước làm cho mẫu vừa máy.`],
 ['Khoảng cách mạng trở thành một chiếc thước nhỏ',`Các mặt nguyên tử trong tinh thể tán xạ neutron theo quan hệ phụ thuộc khoảng cách mạng. Khi vật liệu bị biến dạng đàn hồi, khoảng cách theo những hướng khác nhau thay đổi rất nhỏ, làm vị trí đỉnh nhiễu xạ dịch. So với trạng thái tham chiếu phù hợp, người nghiên cứu suy biến dạng rồi liên hệ với ứng suất qua mô hình đàn hồi.

Cần biết khoảng cách mạng không ứng suất của đúng vật liệu. Thành phần hóa học hoặc pha thay đổi cũng có thể làm đỉnh dịch, nên không được gọi mọi thay đổi là lực. Kết cấu định hướng và độ phân giải không gian còn ảnh hưởng cách đọc.

Neutron có thể đi sâu vào nhiều vật liệu hơn một số phép đo bề mặt, giúp khảo sát phần bên trong. Nhưng thể tích đo vẫn hữu hạn: giá trị là trung bình trong vùng được chọn, không phải lực tại từng điểm nguyên tử.`],
 ['Ứng dụng hôm nay: đưa lịch sử vật liệu vào đánh giá độ bền',`Ứng suất dư có thể hỗ trợ hoặc gây bất lợi tùy hướng, vị trí và kiểu hư hỏng đang xét. Dữ liệu từ đường ray giúp đối chiếu mô hình gia công và tải, rồi nghiên cứu những cách quản lý độ bền. Nó không tự là kết luận một thanh ray cụ thể còn an toàn bao lâu; đánh giá đó cần nhiều phép kiểm khác.

Nhiễu xạ neutron còn được dùng cho mối hàn và các chi tiết kỹ thuật. Khi có thể đo vật nguyên vẹn, người nghiên cứu giảm một phần ảnh hưởng do cắt mẫu, nhưng vẫn phải kiểm chuẩn hình học và mô hình.

Câu chuyện đường ray cho thấy “đứng yên” chỉ mô tả chuyển động bên ngoài. Bên trong một vật rắn, các vùng có thể đang giữ những lực cân bằng nhau. Mạng tinh thể trở thành thước đo để đọc lịch sử ấy. Từ một đỉnh phổ dịch rất nhỏ, người nghiên cứu lần tới những thay đổi mà mắt thường không thể thấy trên bề mặt thép.`],
 ],sources:[['NIST · Ứng suất dư trong các lát đường ray','https://nvlpubs.nist.gov/nistpubs/Legacy/IR/nistir6305.pdf'],['NIST · Đo trên đoạn ray nguyên vẹn, 2004','https://www.govinfo.gov/content/pkg/GOVPUB-C13-fdcd3f8386380b22eea3bf69e06e46a7/pdf/GOVPUB-C13-fdcd3f8386380b22eea3bf69e06e46a7.pdf']]
},
{
 id:'positron-khoang-trong-trong-polymer',category:'khainiem',title:'Một hạt phản vật chất dò những khoảng trống trong polymer',summary:'Thời gian hủy positronium cung cấp thông tin về thể tích tự do. Các màng polymer thấm khí mạnh cho thấy khoảng trống phân tử có thể quan trọng như chính chuỗi polymer.',tags:['PALS','Thể tích tự do','Polymer','Màng'],image:polymer,imageAlt:'Minh họa chuỗi polymer; không phải ảnh các lỗ thể tích tự do',sections:[
 ['Màng đặc vẫn có những khoảng trống rất nhỏ',`Nghiên cứu năm 1998 dùng phổ thời gian sống hủy positron để khảo sát PTMSP và các màng PPO. Những vật liệu có tính vận chuyển đáng chú ý được kiểm tra về phân bố khoảng trống mà phép đo hình học vĩ mô không trực tiếp nhìn thấy. Với PTMSP, dữ liệu cho thấy những miền thể tích tự do lớn hơn nhiều polymer thủy tinh thông thường trong mô hình dùng để phân tích.

Một màng không có lỗ nhìn thấy chưa chắc là khối nguyên tử xếp kín. Các chuỗi và nhóm bên tạo những khoảng không cục bộ, thay đổi theo nhiệt độ và lịch sử xử lý. Những khoảng ấy có thể ảnh hưởng cách phân tử khí đi qua, nhưng cần được đo bằng đầu dò phù hợp với kích thước của chúng.`],
 ['Thời gian tồn tại phản ánh môi trường electron',`Positron có thể kết hợp với electron thành positronium, một trạng thái không bền. Thời gian tồn tại của một thành phần positronium phụ thuộc khả năng tương tác với electron ở vùng xung quanh. Khi nó nằm trong khoảng trống, môi trường biên ảnh hưởng thời gian trước khi hủy.

Các mô hình liên hệ thời gian với kích thước khoang giả định. Phân tích nhiều thành phần hoặc phân bố thời gian có thể cung cấp thông tin về sự không đồng nhất. Tuy nhiên, một bán kính suy ra không phải ảnh trực tiếp của một lỗ hình cầu thật; hình dạng và hóa học môi trường cũng cần được xét.

Cường độ thành phần phổ không luôn là phép đếm đơn giản số lỗ. Quá trình tạo positronium và những tác động hóa học có thể đổi. Vì vậy, PALS mạnh nhất khi được đặt cạnh dữ liệu mật độ, vận chuyển và cấu trúc khác.`],
 ['Ứng dụng hôm nay: nối khoảng trống với chức năng của màng',`PALS được dùng trong nghiên cứu polymer, vật liệu xốp và khuyết tật chất rắn. Tổng quan năm 2023 mô tả cách các nhóm liên hệ thể tích tự do với tính cơ học, nhiệt và vận chuyển. Với một màng khí, biết khoang lớn hơn chưa đủ để dự đoán chọn lọc; đường nối giữa các vùng và tương tác khí–polymer cũng quan trọng.

Phép đo dùng thiết bị chuyên dụng và phân tích thời gian rất ngắn, không phải phương pháp thử tại nhà. Giá trị của nó nằm ở khả năng hỏi một phần cấu trúc thường bị ẩn trong hình vẽ chuỗi.

Câu chuyện này làm rõ rằng vật liệu được tạo bởi cả phần có nguyên tử lẫn những khoảng giữa chúng. Một phản ứng pha tạp hoặc xử lý nhiệt có thể đổi chức năng mà không đổi tên polymer, vì cách chuỗi đóng gói đã đổi. Đo được dấu của những khoảng trống giúp người nghiên cứu đi từ nhận xét “màng thấm hơn” tới giả thuyết cấu trúc có thể kiểm tra.`],
 ],sources:[['Nghiên cứu gốc · Thể tích tự do của màng polymer, 1998','https://doi.org/10.1021/ma971128c'],['Tổng quan phương pháp · PALS và polymer, 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10386335/']]
},
{
 id:'ellipsometry-anh-sang-do-lop-oxide-mong',category:'khainiem',title:'Đo lớp oxide mỏng bằng cách ánh sáng đổi phân cực',summary:'Ellipsometry suy chiều dày và tính quang từ ánh sáng phản xạ. Các so sánh của NIST cho thấy mô hình giao diện có thể quyết định con số cuối cùng.',tags:['Ellipsometry','Màng mỏng','Silicon oxide','Đo lường'],image:spectro,imageAlt:'Minh họa phép đo quang; không phải cấu hình ellipsometer cụ thể',sections:[
 ['Hai máy nhìn cùng màng vẫn cần thống nhất cách hiểu',`Năm 1998, NIST báo cáo nghiên cứu đo những lớp silicon dioxide rất mỏng trên silicon bằng ellipsometry. Các thiết bị có thể cùng đo sự thay đổi phân cực nhưng dùng thiết kế và mô hình phân tích khác nhau. Khi lớp điện môi xuống dưới khoảng chục nanomet, những lựa chọn ấy trở thành phần đáng kể của độ chính xác.

Một chương trình so sánh giữa NIST và VLSI Standards dùng mô hình một lớp với chiết suất cố định cho đối chiếu chính, đồng thời khảo sát mô hình có lớp giao diện. Công việc không chỉ kiểm máy nào cho số gần nhau hơn; nó hỏi những giả định nào đang nối tín hiệu quang với chiều dày vật lý.`],
 ['Tín hiệu trực tiếp là phân cực, chiều dày là kết quả suy ra',`Ánh sáng phản xạ từ các giao diện trong màng trải qua thay đổi biên độ và pha. Ellipsometry đo quan hệ giữa các thành phần phân cực, thường được biểu diễn bằng hai tham số. Mô hình quang học của nền và các lớp được dùng để tìm những giá trị phù hợp với dữ liệu.

Chiều dày và hằng số quang có thể tương quan trong phép khớp. Nếu chỉ đo một bước sóng, nhiều tổ hợp tham số có thể khó phân biệt. Đo theo phổ hoặc nhiều góc bổ sung ràng buộc, nhưng không tự bảo đảm mô hình đã mô tả đúng độ nhám, lớp nhiễm bẩn hay giao diện.

Đây là lý do một độ chính xác hiển thị rất nhỏ không bằng độ đúng của chiều dày. Phần mềm có thể khớp dữ liệu tốt trong một mô hình chưa phù hợp với mẫu thật.`],
 ['Ứng dụng hôm nay: kiểm lớp phủ mà không cần cắt mẫu mỗi lần',`Ellipsometry được dùng trong phát triển màng, linh kiện và theo dõi bề mặt. NIST so các giá trị chiều dày với điện dung–điện áp và hiển vi điện tử để hiểu những khác biệt giữa cách đo. Các phương pháp không nhất thiết cùng định nghĩa một ranh giới trong lớp chuyển tiếp.

Ưu điểm không tiếp xúc và đo nhanh giúp kiểm nhiều vị trí, nhưng mẫu phải phù hợp với giả định về bề mặt và tính đồng đều. Một cấu trúc nhiều pha hoặc tán xạ mạnh có thể cần mô hình khác hoặc kỹ thuật bổ sung.

Câu chuyện oxide trên silicon cho thấy đo lường màng mỏng là cuộc đối thoại giữa dữ liệu và mô hình. Máy ghi ánh sáng đã bị mẫu biến đổi; nhà nghiên cứu cần mô tả mẫu đủ đúng để đọc lại biến đổi ấy. Khi các lớp ngày càng mỏng, những phần từng bị xem là phụ—một lớp bám hay vùng giao diện—có thể chiếm tỷ lệ đáng kể của toàn bộ vật liệu đang được đo.`],
 ],sources:[['NIST · Thin-Film Ellipsometry Metrology, 1998','https://www.nist.gov/publications/thin-film-ellipsometry-metrology'],['NIST · So chiều dày bằng ellipsometry, C–V và HRTEM','https://www.nist.gov/publications/comparison-thickness-values-very-thin-sio2-films-using-ellipsometric-capacitance'],['NIST · Phát triển chuẩn màng mỏng','https://www.nist.gov/publications/semiconductor-measurement-technology-thin-film-reference-materials-development-final']]
},
{
 id:'raman-graphene-laser-vua-nung-vua-do',category:'khainiem',title:'Laser vừa làm nóng graphene vừa giúp đo nó nóng lên bao nhiêu',summary:'Phép đo quang nhiệt dùng dịch chuyển đỉnh Raman như nhiệt kế. Kết quả dẫn nhiệt cần biết cả lượng ánh sáng hấp thụ và đường thoát nhiệt của mẫu.',tags:['Raman','Graphene','Dẫn nhiệt','Đo nhiệt'],image:'/assets/library/photos/elements/C.jpg',imageAlt:'Carbon minh họa nguyên tố; không phải màng graphene treo trong phép đo',sections:[
 ['Một màng chỉ dày một lớp nguyên tử khó gắn nhiệt kế',`Năm 2008, nhóm Alexander Balandin báo cáo phép đo độ dẫn nhiệt của graphene đơn lớp treo qua một rãnh. Laser hội tụ làm nóng vùng mẫu, trong khi sự dịch chuyển đỉnh G trong phổ Raman được dùng để suy mức tăng nhiệt độ. Một thiết bị quang trở thành nhiệt kế không tiếp xúc cho vật liệu cực mỏng.

Trước bước gia nhiệt, nhóm hiệu chuẩn vị trí đỉnh theo nhiệt độ bằng công suất laser thấp để giảm tự làm nóng. Sau đó tăng công suất và theo dõi đáp ứng. Sự tách hai bước giúp tránh dùng chính điều chưa biết làm chuẩn cho phép đo.

Các giá trị lớn được báo cáo gắn với mẫu treo và điều kiện của nghiên cứu, không phải một con số mặc định cho mọi lớp graphene trên mọi nền.`],
 ['Đỉnh phổ cần được nối với một mô hình dòng nhiệt',`Dao động mạng thay đổi theo nhiệt độ, làm đặc trưng Raman dịch. Nhưng ứng suất, pha tạp và khuyết tật cũng có thể ảnh hưởng phổ. Để dùng một đỉnh như nhiệt kế, cần kiểm tra các nguồn dịch khác và giữ cấu hình đo nhất quán.

Độ dẫn nhiệt không xuất hiện trực tiếp trên trục Raman. Nó được suy từ công suất hấp thụ, nhiệt độ tăng và hình học đường truyền tới những vùng tản nhiệt. Lượng laser chiếu tới không đồng nhất với lượng năng lượng graphene thực sự nhận; phần phản xạ, truyền qua và hấp thụ phải được đánh giá.

Mẫu có tiếp xúc với nền sẽ có thêm đường thoát nhiệt, còn rìa và khuyết tật ảnh hưởng chuyển động phonon. Vì vậy, việc so các công trình cần nhìn cả cấu trúc mẫu và điều kiện biên thay vì chỉ so con số lớn nhất.`],
 ['Ứng dụng hôm nay: đọc nhiệt trong vật liệu hai chiều',`Phương pháp quang nhiệt Raman được mở rộng cho những màng mỏng và vật liệu hai chiều có đỉnh phù hợp. Các mô tả kỹ thuật của nhóm Balandin trình bày việc đo công suất hấp thụ bằng những cấu hình khác nhau trong các nghiên cứu sau, cho thấy phép đo tiếp tục được cải tiến cùng hiểu biết về nguồn sai số.

Trong thiết kế điện tử, khả năng tản nhiệt của một vật liệu cao chưa tự bảo đảm toàn bộ linh kiện mát hơn. Điện trở nhiệt tiếp xúc, lớp nền và hình học có thể giới hạn hệ thống. Dữ liệu vật liệu là một đầu vào cần thiết, không phải câu trả lời cuối cho thiết bị.

Câu chuyện graphene làm rõ cách một đặc tính quang có thể trở thành đầu dò cho một đại lượng nhiệt. Laser không chỉ soi mẫu; nó cũng tác động lên mẫu. Khi tác động ấy được đo và mô hình hóa, người nghiên cứu có thể khai thác nó có chủ đích. Phép đo tốt bắt đầu từ việc biết ánh sáng đã mang bao nhiêu năng lượng vào và năng lượng ấy có thể đi ra bằng những con đường nào.`],
 ],sources:[['Balandin và cộng sự · Độ dẫn nhiệt graphene, 2008','https://doi.org/10.1021/nl0731872'],['Nhóm Balandin · Nguyên lý và hiệu chuẩn phép quang nhiệt','https://balandin-group.ucla.edu/balandin-optothermal-technique/']]
},

{
 id:'terahertz-lop-vo-vien-thuoc',category:'khainiem',title:'Nhìn chiều dày lớp bao viên nén bằng tiếng vọng terahertz',summary:'Xung terahertz phản xạ ở các giao diện giúp đo lớp phủ mà không cắt viên. Dữ liệu không phá hủy bổ sung cho kiểm tra khối lượng và hòa tan.',tags:['Terahertz','Lớp phủ','Đo chiều dày'],image:spectro,imageAlt:'Minh họa đo phổ; không phải ảnh thiết bị hoặc viên thuốc được khảo sát',sections:[
 ['Hai viên có lớp bao được so trước khi cắt',`Công trình của Fitzgerald, Cole và Taday, thuộc tập báo năm 2005, dùng ảnh xung terahertz để khảo sát lớp bao của hai sản phẩm ibuprofen. Bản đồ được so với ảnh mặt cắt và cho sự phù hợp trong những mẫu khảo sát. Phép đo mở khả năng kiểm tra cấu trúc lớp mà không cần phá từng viên.

Lớp bao có thể tham gia kiểm soát giải phóng hoặc bảo vệ sản phẩm. Cân khối lượng tăng của cả mẻ chỉ cho một giá trị trung bình, không nói lớp ở từng mặt và từng viên đều đến đâu. Một công cụ có thông tin không gian vì vậy trả lời câu hỏi khác với phép cân.

Bài này nói về đo vật liệu, không dùng chiều dày để hướng dẫn thay đổi hay sử dụng thuốc.`],
 ['Xung trở lại từ những ranh giới khác nhau',`Khi xung đi tới một giao diện có tính quang khác, một phần phản xạ. Những phản xạ từ mặt ngoài và ranh giới lớp bao–lõi có thời gian đến khác nhau. Nếu biết chiết suất thích hợp, chênh lệch thời gian có thể được liên hệ với chiều dày.

Không phải mọi lớp mỏng đều được phân giải dễ dàng. Độ rộng xung, tán xạ và hình học bề mặt giới hạn phép đo. Mép sắc hoặc chữ dập trên viên có thể làm thu tín hiệu khó hơn vùng tương đối phẳng. Mẫu nhiều lớp cần mô hình để tránh gán nhầm những đỉnh chồng nhau.

Nước hấp thụ mạnh ở nhiều vùng terahertz, nên thành phần và trạng thái mẫu ảnh hưởng cách ánh sáng đi qua. Một phương pháp tốt cho viên khô không tự áp dụng cho mọi dạng bào chế. Cần xác nhận trên loại vật liệu và chiều dày thực tế.`],
 ['Ứng dụng hôm nay: kiểm quá trình thay vì chỉ kiểm cuối mẻ',`Tổng quan năm 2020 mô tả các nghiên cứu theo dõi lớp bao ở quy mô phòng thí nghiệm và sản xuất. Những thay đổi như trộn kém hoặc thêm viên chưa phủ có thể hiện thành phân bố chiều dày khác. Dữ liệu giúp liên hệ điều kiện vận hành với cấu trúc sản phẩm.

Tốc độ, độ ổn định thiết bị và chi phí vẫn quyết định mức triển khai. Kỹ thuật không thay thế mọi phép thử hòa tan hay chất lượng hóa học; nó bổ sung thông tin hình học mà những phép khác khó cung cấp trực tiếp.

Câu chuyện terahertz cho thấy một lớp rất mỏng có thể được hỏi bằng thời gian ánh sáng đi và về. Mỗi giao diện tạo một dấu trong tín hiệu, nhưng đọc đúng cần biết vật liệu giữa các giao diện. Khi kết hợp với dữ liệu chức năng, phép đo giúp chuyển từ nhận xét “lớp bao có vẻ đều” sang bản đồ và phân bố có thể đối chiếu giữa các mẻ.`],
 ],sources:[['Fitzgerald và cộng sự · Đo lớp bao không phá hủy','https://doi.org/10.1002/jps.20225'],['Tổng quan TPI cho lớp bao dược phẩm, 2020','https://pmc.ncbi.nlm.nih.gov/articles/PMC7085697/']]
},
{
 id:'phan-xa-neutron-doc-lop-mang-trong-nuoc',category:'khainiem',title:'Một màng lipid trong nước được đọc theo chiều từ mặt này sang mặt kia',summary:'Phản xạ neutron tạo hồ sơ cấu trúc theo chiều sâu của màng. Chọn tương phản và góc đo giúp phân biệt những phần vốn chồng tín hiệu.',tags:['Phản xạ neutron','Màng lipid','Giao diện'],image:polymer,imageAlt:'Minh họa tổ chức phân tử; không phải mô hình màng lipid từ dữ liệu neutron',sections:[
 ['Giữ màng ngậm nước trong lúc đo',`Trong tài liệu phương pháp năm 2019, nhóm NIST mô tả phản xạ neutron để nghiên cứu màng lipid và protein liên quan. Màng mô hình có thể được giữ trong môi trường nước, giúp khảo sát cấu trúc theo chiều vuông góc với bề mặt mà không buộc phải làm khô mẫu.

Câu hỏi thường là protein nằm ở ngoài, xuyên vào hay làm thay đổi lớp nào của màng. Một ảnh trung bình toàn phức khó phân biệt các khả năng ấy. Phản xạ cung cấp một hồ sơ theo độ sâu để kiểm tra mô hình.

Những màng nâng đỡ hoặc neo trên nền vẫn khác màng tự do của tế bào. Thiết kế phải xét ảnh hưởng của nền, độ linh động và thành phần trước khi liên hệ kết quả tới chức năng sinh học.`],
 ['Cường độ phản xạ mang thông tin giao diện',`Chùm neutron tới mặt mẫu ở các góc phù hợp, và cường độ phản xạ được đo theo động lượng truyền. Những ranh giới có mật độ chiều dài tán xạ khác nhau tạo dấu trong đường phản xạ. Mô hình các lớp được dùng để suy chiều dày, độ nhám và mức ngậm nước.

Hydrogen và deuterium tạo tương phản khác nhau, nên thay tỷ lệ nước thường–nước nặng cung cấp thêm các cách nhìn. Một thành phần có thể ít nổi bật ở điều kiện này nhưng rõ hơn ở điều kiện khác. Không cần tháo phức để tìm từng phần, nhưng phải kiểm tra việc thay đồng vị không làm hệ đổi ngoài dự kiến.

Bài toán nghịch không luôn có nghiệm duy nhất. Nhiều cấu trúc có thể tạo đường phản xạ gần nhau; dữ liệu ở nhiều tương phản và những ràng buộc hóa học giúp phân biệt. Độ phân giải được nêu là khả năng của phép đo trong điều kiện cụ thể, không phải ảnh từng phân tử.`],
 ['Ứng dụng hôm nay: thiết kế phép đo trước khi dùng thời gian nguồn neutron',`Nghiên cứu tối ưu thiết kế năm 2021 dùng các hệ màng lipid để khảo sát lựa chọn góc, tương phản và phân bổ thời gian đo. Kết quả cho thấy chiến lược thu dữ liệu có thể cải thiện đáng kể thông tin về tham số cần biết mà không chỉ kéo dài mọi phép đo như nhau.

Phản xạ neutron hỗ trợ nghiên cứu protein màng, lớp phủ và những giao diện mềm. Nó thường được phối hợp với các phép đo hoạt tính hoặc hình ảnh để xác định một thay đổi cấu trúc có ý nghĩa chức năng gì.

Câu chuyện này nhấn mạnh rằng quan sát tốt bắt đầu từ câu hỏi cụ thể. Nếu cần biết một protein chạm lớp đầu phân cực hay đi vào vùng kỵ nước, phải chọn điều kiện làm hai mô hình cho tín hiệu khác nhau. Một màng mỏng chỉ vài nanomet không thể tự kể chuyện; người nghiên cứu tạo các góc nhìn bổ sung để những lớp bên trong có cơ hội được phân biệt.`],
 ],sources:[['NIST · Protein màng và phản xạ neutron','https://www.nist.gov/publications/structural-investigations-membrane-associated-proteins-neutron-reflectometry'],['Nghiên cứu gốc · Tối ưu thiết kế phép phản xạ neutron','https://arxiv.org/abs/2108.05605']]
},
{
 id:'giwaxs-mang-pin-huu-co-doi-huong',category:'khainiem',title:'Trong màng pin hữu cơ, phân tử không chỉ cần đứng đúng chỗ mà còn đúng hướng',summary:'GIWAXS khảo sát trật tự và định hướng trong lớp hoạt tính mỏng. Các phép so với nhiễu xạ electron giúp kiểm tra phần cấu trúc mà mỗi phương pháp thực sự đo được.',tags:['GIWAXS','Màng hữu cơ','Định hướng','Pin quang điện'],image:polymer,imageAlt:'Minh họa vật liệu hữu cơ; không phải cấu trúc lớp hoạt tính cụ thể',sections:[
 ['Màng mỏng có nhiều miền cùng chia công việc',`Tổng kết năm 2014 về pin mặt trời hữu cơ mô tả vai trò của các kỹ thuật tán xạ góc tới nhỏ trong đọc hình thái lớp hoạt tính. Thành phần cho và nhận điện tử cần được tổ chức để năng lượng kích thích được tách và điện tích có đường tới điện cực. Cùng một công thức pha trộn có thể tạo hiệu năng khác nếu quá trình làm màng thay đổi.

GIWAXS, tán xạ tia X góc rộng ở góc tới nhỏ, cung cấp thông tin về trật tự gần và định hướng của các miền có cấu trúc. GISAXS đọc những thang lớn hơn, nên hai phép đo thường bổ sung nhau.

Người nghiên cứu không chỉ muốn biết màng có tinh thể hay không, mà muốn biết các khoảng cách và hướng ưu tiên ấy có phù hợp với đường vận chuyển cần dùng.`],
 ['Góc tới nhỏ giúp tín hiệu của màng nổi lên',`Một lớp hoạt tính rất mỏng nằm trên nền dày tạo khó khăn nếu phần nền đóng góp quá mạnh. Hình học góc tới nhỏ tăng tương tác với lớp gần bề mặt trong điều kiện phù hợp. Detector hai chiều ghi sự phân bố tán xạ, giúp phân biệt hướng trong mặt và ngoài mặt màng.

Đỉnh hoặc cung tán xạ có thể liên quan đến cách các chuỗi, mặt phẳng thơm hoặc miền tinh thể sắp xếp. Tuy nhiên, một ảnh nhiều cung đẹp chưa tự mô tả toàn bộ mạng đường đi của điện tích. Những phần vô định hình và miền nhỏ có thể đóng vai trò quan trọng dù khó thấy bằng cùng một dấu.

Độ sâu thăm dò, góc chiếu và cách nền được xử lý cần được báo cáo. Một thay đổi cường độ có thể do lượng vật liệu định hướng đổi, chứ không chỉ do mức kết tinh tăng.`],
 ['Ứng dụng hôm nay: kiểm tra cấu trúc bằng các đầu dò khác nhau',`Công trình năm 2025 so sánh nhiễu xạ electron ba chiều với GIWAXS trên hệ DRCN5T:PC₇₁BM được xử lý bằng hơi dung môi. Việc đối chiếu giúp xác định những thông số cấu trúc nào nhất quán và mỗi kỹ thuật có giới hạn nào. Một phương pháp mới có giá trị khi được so trên cùng vật liệu, không chỉ được gọi là độ phân giải cao hơn.

Trong phát triển pin hữu cơ, dữ liệu cấu trúc cần được đặt cạnh phổ quang, phép đo điện và độ bền. Tối ưu một hướng sắp xếp có thể làm tốt vận chuyển nhưng thay đổi phân tách pha theo cách khác; không có một dấu GIWAXS duy nhất bảo đảm hiệu suất cao.

Câu chuyện màng pin cho thấy gia công là một phần của hóa học chức năng. Các phân tử giống nhau có thể tạo nhiều kiến trúc, và ánh sáng chỉ trở thành dòng điện khi kiến trúc ấy cho phép các bước tiếp nối diễn ra. GIWAXS giúp đọc một phần trật tự trong màng để quá trình thiết kế bớt dựa vào thử công thức một cách mù mờ.`],
 ],sources:[['Tổng kết · Hình thái pin hữu cơ bằng GIXS, 2014','https://pubmed.ncbi.nlm.nih.gov/24677365/'],['Nghiên cứu gốc · So 3D ED và GIWAXS, 2025','https://arxiv.org/abs/2502.11254']]
},
{
 id:'nmr-ran-amyloid-trat-tu-trong-soi',category:'khainiem',title:'Sợi protein không cần thành tinh thể đẹp mới kể được cấu trúc',summary:'NMR trạng thái rắn đo các ràng buộc khoảng cách trong sợi amyloid. Những kết quả đầu thế kỷ XXI cho thấy hình dạng sợi tương tự có thể chứa nhiều cách tổ chức phân tử.',tags:['NMR trạng thái rắn','Amyloid','Cấu trúc','Đồng vị'],image:polymer,imageAlt:'Minh họa chuỗi protein; không phải cấu trúc của một loại sợi amyloid cụ thể',sections:[
 ['Một đối tượng khó với các cách đo quen thuộc',`Năm 2002, nhóm Robert Tycko công bố những ràng buộc cấu trúc của sợi tạo bởi peptide Aβ₁₋₄₀ bằng NMR trạng thái rắn. Các phép đo tương tác giữa những vị trí carbon-13 được đánh dấu hỗ trợ cách sắp xếp các chuỗi song song trong vùng được khảo sát, đồng thời cho thấy phần đầu chuỗi có mức mất trật tự khác.

Sợi amyloid không dễ tạo đơn tinh thể phù hợp cho phương pháp thông thường, còn kích thước và tính ít hòa tan gây khó cho NMR dung dịch. NMR trạng thái rắn mở một cách tiếp cận khác, không đòi mẫu phải đáp ứng cùng điều kiện của hai phương pháp ấy.

Đây là nghiên cứu cấu trúc của những mẫu xác định, không phải một mô hình duy nhất được áp cho mọi amyloid hay mọi trạng thái trong cơ thể.`],
 ['Giữ thông tin khoảng cách trong tín hiệu cộng hưởng',`Trong chất rắn, các tương tác định hướng làm phổ rộng hơn so với nhiều mẫu dung dịch quay nhanh. Quay mẫu ở góc ma thuật và những chuỗi xung phù hợp giúp thu những loại thông tin khác nhau: có thể làm hẹp phổ hoặc khôi phục tương tác cần để đo khoảng cách.

Dịch chuyển hóa học góp phần nhận diện cấu trúc cục bộ, còn tương tác giữa các hạt nhân cung cấp ràng buộc về vị trí tương đối. Đánh dấu đồng vị cho phép tập trung vào những phần cần hỏi, nhưng mọi ràng buộc vẫn phải được ghép thành mô hình có thể kiểm tra.

Một khoảng cách phù hợp không tự chứng minh toàn bộ hình học của sợi. Cần đủ dữ liệu ở nhiều cấp và kiểm các cấu trúc cạnh tranh. Việc một vùng có phổ sắc cho thấy trật tự cục bộ, trong khi những vùng khác có thể vẫn linh động hoặc không đồng nhất.`],
 ['Ứng dụng hôm nay: phân biệt các trạng thái cấu trúc thay vì chỉ tên protein',`Các tổng kết của Tycko mô tả sự phát triển mô hình phân tử cho nhiều loại sợi và sự tồn tại của những dạng cấu trúc khác nhau. Cùng một trình tự có thể tổ chức thành các dạng sợi khác tùy lịch sử và môi trường, nên danh tính hóa học của chuỗi chưa đủ mô tả vật liệu tạo thành.

NMR trạng thái rắn hiện được phối hợp với cryo-EM và những phép đo khác để kiểm tra cấu trúc và động học. Thông tin này hỗ trợ nghiên cứu cơ bản về trạng thái protein; nó không tự đưa ra một kết luận điều trị hay dự đoán bệnh cho cá nhân.

Câu chuyện amyloid cho thấy “không có tinh thể tốt” không phải điểm dừng của hóa học cấu trúc. Mỗi phương pháp tương tác với mẫu theo cách riêng, và đôi khi một kỹ thuật khó hơn về xử lý tín hiệu lại giữ được những câu hỏi mà kỹ thuật khác không tiếp cận thuận lợi. Các ràng buộc nhỏ từ nhiều vị trí dần làm những mô hình không phù hợp phải rời cuộc tranh luận.`],
 ],sources:[['Nghiên cứu gốc · Aβ₁₋₄₀ bằng NMR rắn, 2002','https://doi.org/10.1016/S0006-3495(02)75244-2'],['Tycko · NMR rắn và cấu trúc amyloid, 2011','https://pmc.ncbi.nlm.nih.gov/articles/PMC3191906/']]
},

{
 id:'muon-spin-nghe-tu-truong-ben-trong',category:'khainiem',title:'Một hạt sống ngắn làm đầu dò từ trường bên trong vật liệu',summary:'Muon spin rotation đọc phân bố từ trường cục bộ trong chất siêu dẫn. Tín hiệu phân rã giúp nghiên cứu những vùng mà phép đo trung bình ngoài mẫu khó phân biệt.',tags:['Muon','Siêu dẫn','Từ trường cục bộ'],image:spectro,imageAlt:'Minh họa phân tích tín hiệu; không phải sơ đồ nguồn muon',sections:[
 ['Đưa đầu dò vào chính nơi cần đo',`Trong nghiên cứu năm 2008 về chất siêu dẫn graphite xen calcium CaC₆, các tác giả dùng muon spin rotation để khảo sát độ xuyên từ. Một chùm muon phân cực được đưa vào mẫu, và sự tiến động spin phản ánh từ trường tại những vị trí hạt dừng lại. Dữ liệu theo nhiệt độ giúp ràng buộc cách mô tả trạng thái siêu dẫn.

Đây là phép đo khác với đặt một cảm biến từ bên ngoài rồi đọc tổng tín hiệu. Nó nhạy với môi trường cục bộ và phân bố trong thể tích được khảo sát. Những miền có tính từ hoặc siêu dẫn khác nhau có thể để lại dấu riêng trong dạng suy giảm.

PSI mô tả ưu thế này trong nghiên cứu vật liệu có sự cạnh tranh giữa từ tính và siêu dẫn, nơi một giá trị trung bình có thể che những pha cùng tồn tại.`],
 ['Phân rã mang theo thông tin về hướng spin',`Muon không tồn tại lâu. Hướng phát của hạt sinh ra khi nó phân rã có liên hệ thống kê với hướng spin tại thời điểm đó. Ghi số sự kiện theo thời gian ở các detector tạo đường phân cực, từ đó suy những đặc điểm của trường tại vị trí muon.

Trong chất siêu dẫn loại II có từ trường ngoài, mạng xoáy từ tạo phân bố trường không đồng đều. Độ rộng và hình dạng phân bố có thể liên hệ với các tham số như độ xuyên từ thông qua mô hình phù hợp. Vị trí dừng, nền từ giá mẫu và độ không đồng nhất cần được xét.

Một tín hiệu thay đổi không tự chỉ ra duy nhất cơ chế ghép cặp. Phải so sự phụ thuộc nhiệt độ, trường và các phép đo khác. Muon là đầu dò mạnh nhưng vẫn tương tác với mẫu, nên câu hỏi về ảnh hưởng cục bộ của nó cũng có thể quan trọng.`],
 ['Ứng dụng hôm nay: phân biệt thể tích và trạng thái cục bộ',`Các cơ sở muon dùng phương pháp này để nghiên cứu từ tính yếu, dao động spin và chất siêu dẫn. Nó bổ sung cho neutron, NMR và đo từ khối, mỗi kỹ thuật nhạy với những thang thời gian và không gian khác nhau.

Nguồn muon là hạ tầng chuyên dụng, nên thí nghiệm cần thiết kế để khai thác tốt thời gian đo. Kết luận về một vật liệu phải gắn với thành phần và điều kiện cụ thể; không thể gán dữ liệu CaC₆ cho mọi chất chứa carbon hoặc calcium.

Câu chuyện cho thấy một đầu dò có tuổi thọ ngắn vẫn có thể mang thông tin lâu dài. Người nghiên cứu không giữ muon lại để xem mãi; họ dùng chính sự phân rã như một đồng hồ đọc spin. Những sự kiện riêng lẻ được tích lũy thành thống kê, rồi thống kê trở thành bằng chứng về các trường rất nhỏ và không đồng đều trong chất rắn.`],
 ],sources:[['Nghiên cứu gốc · Muon trong CaC₆, 2008','https://arxiv.org/abs/0803.4513'],['PSI · Nghiên cứu bằng muon cục bộ','https://www.psi.ch/en/bulk-musr/research']]
},
{
 id:'electrospinning-dien-truong-keo-soi',category:'khainiem',title:'Điện trường kéo một dòng polymer thành những sợi rất mảnh',summary:'Electrospinning dùng chuyển động điện–thủy động để tạo sợi. Tính chất dung dịch và đường đi của tia lỏng quyết định vật liệu cuối, không chỉ tên polymer.',tags:['Electrospinning','Sợi nano','Điện–thủy động'],image:polymer,imageAlt:'Minh họa chuỗi polymer; không phải ảnh sợi electrospinning',sections:[
 ['Một cách kéo sợi không dùng cùng cơ chế với kéo sợi dệt',`Năm 1995, Doshi và Reneker mô tả quá trình điện trường tạo tia dung dịch polymer mang điện. Khi tia đi qua không khí, dung môi bay hơi và để lại sợi có hình dạng, kích thước phụ thuộc vật liệu và điều kiện. Công trình báo cáo các đường kính từ dưới micromet tới vài micromet, không phải mọi sợi đều cùng kích thước nano.

Quá trình có lịch sử từ trước đó; nghiên cứu của nhóm Reneker góp phần làm nổi bật miền ứng dụng của các sợi rất mảnh. Những lớp sợi tạo diện tích bề mặt lớn và cấu trúc lỗ rỗng có thể điều chỉnh, hấp dẫn cho lọc và vật liệu chức năng.

Điều cần hiểu là điện trường không biến một polymer bất kỳ thành sợi tốt theo cùng một công thức. Dung dịch phải có hành vi phù hợp để tia kéo dài mà không chỉ vỡ thành giọt.`],
 ['Điện tích, sức căng và sự vướng chuỗi cạnh tranh',`Lực điện tác động lên chất lỏng mang điện, trong khi sức căng bề mặt có xu hướng giữ hình giọt. Độ nhớt và sự vướng của các chuỗi giúp tia duy trì tính liên tục. Nếu khả năng kết nối chuỗi không đủ, có thể xuất hiện hạt hoặc những đoạn sợi không đều.

Trong quá trình bay, tia có thể uốn và kéo dài mạnh. Bay hơi làm nồng độ polymer và tính cơ học thay đổi liên tục. Độ ẩm, dung môi và khoảng đường tới bộ thu vì thế ảnh hưởng bề mặt sợi, độ rỗng và khả năng dính giữa các sợi.

Các nghiên cứu về sợi điện kéo phân biệt nguyên liệu dung dịch với nguyên liệu nóng chảy. Hai trường hợp cùng dùng lực điện nhưng có đường làm rắn khác, nên lựa chọn thiết bị và tính chất đầu vào không thể hoán đổi đơn giản.`],
 ['Ứng dụng hôm nay: chức năng của cả lớp sợi',`Electrospinning được nghiên cứu cho lọc, composite và những nền vật liệu sinh học. Đường kính sợi nhỏ có thể tăng diện tích tương tác, nhưng hiệu quả lọc còn phụ thuộc độ dày lớp, phân bố lỗ và tổn thất áp suất. Một ảnh SEM đẹp không thay phép thử chức năng.

Những ứng dụng tiếp xúc cơ thể hoặc môi trường đặc biệt cần đánh giá riêng về thành phần còn dư, độ bền và tính tương thích. Khả năng tạo sợi không tự chứng minh sản phẩm đã đạt các yêu cầu đó.

Câu chuyện điện kéo làm rõ việc cấu trúc vật liệu được tạo trong một dòng đang thay đổi. Chuỗi polymer, dung môi và điện tích cùng di chuyển trước khi bị giữ thành sợi. Khi hiểu các bước ấy, người thiết kế có thể điều chỉnh cả cấu trúc sợi lẫn cách chúng xếp thành mạng. Vật liệu cuối không chỉ là polymer ở kích thước nhỏ hơn, mà là một kiến trúc được hình thành từ lịch sử dòng chảy và làm rắn.`],
 ],sources:[['Doshi và Reneker · Quá trình electrospinning, 1995','https://doi.org/10.1016/0304-3886(95)00041-8'],['Chuyên khảo · Sợi tạo bằng electrospinning','https://www.cambridge.org/core/books/abs/fibrous-materials/electrospun-fibers/F129BC5DB911440CB9356A47E0478476']]
},
{
 id:'dien-tham-dong-chat-long-trong-chip',category:'khainiem',title:'Một bề mặt tích điện có thể kéo cả dòng chất lỏng đi',summary:'Điện thẩm hỗ trợ bơm và định lượng mẫu trong chip phân tích. Điện tích ở thành kênh trở thành một phần của thiết bị vận chuyển.',tags:['Điện thẩm','Vi lưu','Bề mặt','Chip'],image:'/assets/library/apparatus-voltaic-pile.svg',imageAlt:'Minh họa điện hóa; không phải sơ đồ điện áp vận hành của chip',sections:[
 ['Giảm kích thước bình cũng phải giảm cách đưa mẫu',`Trong công trình năm 1994, Manz và cộng sự khảo sát bơm điện thẩm và phân tách điện di cho các hệ phân tích thu nhỏ. Họ đặc trưng dòng và trộn ở những kênh phân nhánh, đồng thời dùng điều khiển điện để đưa những phần mẫu nhỏ vào vùng tách.

Khi thể tích giảm, một bơm cơ học lớn nối với nhiều ống có thể trở thành phần khó điều khiển. Điện thẩm khai thác bề mặt kênh để tạo chuyển động, mở cách tích hợp vận chuyển với phép phân tích.

Tuy nhiên, đưa dòng tới một nút giao không có nghĩa mẫu đã trộn đều. Trong vi kênh, khuếch tán và thời gian lưu vẫn quyết định các dòng gặp nhau theo cách nào. Thiết kế phải phân biệt chức năng bơm, nạp mẫu và trộn.`],
 ['Lớp ion gần thành kéo theo dung môi',`Thành kênh có điện tích cố định được bù bởi ion trong dung dịch. Khi có điện trường dọc kênh, phần ion di động trong lớp gần bề mặt chịu lực và truyền chuyển động cho chất lỏng. Dòng điện thẩm vì vậy khác điện di của một chất tan riêng lẻ, dù hai hiện tượng có thể xảy ra đồng thời.

Hóa học bề mặt, pH và lực ion ảnh hưởng lớp điện kép và tốc độ dòng. Protein hoặc chất khác bám lên thành có thể làm dòng đổi theo thời gian. Một chip giữ nguyên hình học vẫn có thể hoạt động khác sau khi tiếp xúc nhiều mẫu.

Nhiệt do dòng điện và phản ứng ở điện cực cũng cần được quản lý. Không thể xem điện trường như một công tắc không tác động hóa học đến hệ. Các điều kiện phù hợp phải giữ mẫu và dung dịch trong miền ổn định của phương pháp.`],
 ['Ứng dụng hôm nay: bề mặt là một bộ phận vận hành',`Các tổng kết về micropump mô tả điện thẩm như một lựa chọn cho vi hệ, với ưu điểm và giới hạn riêng so với bơm cơ học hoặc các lực khác. Việc chọn phụ thuộc dung dịch, áp suất cần vượt và khả năng kiểm soát bề mặt.

Trong phân tích trên chip, độ lặp lại của nạp mẫu quan trọng vì nó ảnh hưởng trực tiếp hình dạng đỉnh và định lượng. Những thay đổi nhỏ của độ dẫn hoặc thành kênh có thể làm lượng mẫu đi vào khác, nên kiểm chuẩn phải đi cùng quá trình thu nhỏ.

Câu chuyện điện thẩm cho thấy lớp bề mặt rất mỏng có thể điều khiển một dòng chất lỏng lớn hơn nó nhiều. Thay vì chỉ coi thành kênh là vật chứa trơ, người thiết kế dùng hóa học tại đó như động cơ. Sự tích hợp này giúp làm thiết bị nhỏ gọn, nhưng cũng khiến việc hiểu và duy trì trạng thái bề mặt trở thành điều kiện của phép đo đáng tin.`],
 ],sources:[['Manz và cộng sự · Bơm điện thẩm trên vi hệ, 1994','https://doi.org/10.1088/0960-1317/4/4/010'],['Tổng kết micropump và cơ chế điện thẩm','https://web.stanford.edu/group/microfluidics/Publications/Micropumps_Cooling/Laser%20Review%20of%20Micropumps%20in%20JMM.pdf']]
},
{
 id:'dien-di-dien-moi-te-bao-chon-duong',category:'khainiem',title:'Một điện trường không đều khiến những tế bào chọn đường khác nhau',summary:'Dielectrophoresis khai thác khác biệt phân cực thay vì chỉ điện tích tổng. Thí nghiệm nấm men năm 1966 mở một hướng tách tế bào bằng tính chất vật lý.',tags:['Dielectrophoresis','Phân cực','Tế bào','Vi lưu'],image:'/assets/library/ionic-crystal.svg',imageAlt:'Minh họa đáp ứng điện; không phải mô hình điện môi đầy đủ của tế bào',sections:[
 ['Tế bào sống và chết không phản ứng giống nhau',`Năm 1966, Pohl và Hawk dùng điện trường tần số cao không đồng đều để khảo sát hỗn hợp tế bào nấm men sống và chết. Những tế bào sống được tách trong thí nghiệm vẫn giữ khả năng sống sau quá trình. Kết quả cho thấy có thể khai thác khác biệt điện môi để tạo sự phân chia mà không cần một nhãn nhận diện riêng cho từng tế bào.

Lịch sử lĩnh vực sau đó đi qua các điện cực vi chế tạo và nhiều thiết kế kênh. Thu nhỏ giúp tạo gradient trường theo hình học kiểm soát hơn, đồng thời phối hợp tách với các bước phân tích khác.

Câu chuyện cần giữ đúng phạm vi: kết quả với nấm men trong một môi trường xác định không chứng minh mọi loại tế bào có thể tách sống–chết bằng cùng một điều kiện.`],
 ['Lực có thể xuất hiện dù vật không mang điện tích ròng lớn',`Trong dielectrophoresis, vật bị phân cực trong điện trường không đều. Sự khác nhau giữa đáp ứng của vật và môi trường tạo lực hướng về vùng trường mạnh hơn hoặc yếu hơn tùy điều kiện. Đây là cơ chế khác với lực điện di đơn giản trên điện tích ròng.

Tế bào có màng, bên trong và lớp bề mặt với tính điện khác nhau. Tần số quyết định những phần nào góp mạnh vào đáp ứng. Khi màng thay đổi hoặc môi trường có độ dẫn khác, hướng và độ lớn lực có thể đổi.

Vì vậy, tách bằng trường không phải đọc một đặc tính bất biến giống nhãn tên. Tình trạng tế bào, kích thước và dung dịch đều cần được khảo sát. Dòng điện cũng có thể tạo nhiệt hoặc dòng chất lỏng phụ, nên phải phân biệt lực mong muốn với những tác động đi kèm.`],
 ['Ứng dụng hôm nay: tích hợp nhưng vẫn cần kiểm chất lượng mẫu',`Tổng kết năm 2016 mô tả nhiều cách dùng dielectrophoresis để giữ, phân loại và vận chuyển tế bào trong vi hệ. Nghiên cứu ADEPT năm 2024 tiếp tục phát triển nền tảng nhỏ gọn cho những công việc ấy, cho thấy kỹ thuật vẫn đang được điều chỉnh theo nhu cầu sử dụng.

Khi đánh giá hệ tách, độ tinh khiết của phần thu được phải đi cùng tỷ lệ thu hồi và trạng thái mẫu sau xử lý. Giữ được nhiều đối tượng không đồng nghĩa đã phân biệt tốt, còn tách rất chọn lọc có thể làm mất quá nhiều mẫu.

Điều đáng nhớ là vật chất có thể được nhận diện qua cách nó phân cực. Một trường được tạo hình phù hợp biến sự khác biệt vi mô thành đường đi khác nhau trong kênh. Cách tách ấy mở thêm lựa chọn cho nghiên cứu tế bào, nhưng giá trị chỉ rõ khi cả tính chọn lọc, khả năng lặp lại và tác động lên đối tượng được kiểm chứng cùng nhau.`],
 ],sources:[['Pohl và Hawk · Tách nấm men sống–chết, 1966','https://pubmed.ncbi.nlm.nih.gov/17779503/'],['Tổng kết 50 năm tách tế bào bằng DEP','https://pmc.ncbi.nlm.nih.gov/articles/PMC4930443/'],['Nghiên cứu gốc · Nền tảng ADEPT, 2024','https://www.nature.com/articles/s41378-024-00654-z']]
},

{
 id:'electrowetting-giot-nuoc-di-theo-dien-cuc',category:'khainiem',title:'Giọt nước bước từ ô này sang ô khác theo lệnh điện',summary:'Electrowetting thay đổi điều kiện thấm ướt để vận chuyển giọt riêng. Thiết kế bề mặt và lớp cách điện quyết định giọt có đi rồi trở lại ổn định hay không.',tags:['Electrowetting','Vi lưu số','Thấm ướt'],image:'/assets/library/apparatus-voltaic-pile.svg',imageAlt:'Minh họa điện hóa; không phải sơ đồ chế tạo hay điều kiện điện áp của chip',sections:[
 ['Một dãy điện cực làm đường đi cho giọt',`Năm 2000, Pollack, Fair và Shenderov báo cáo thiết bị dùng điện để di chuyển các giọt dung dịch nhỏ giữa các điện cực phẳng trên kính. Nguyên mẫu cho thấy thao tác lặp lại được, mở một hướng vi lưu trong đó từng giọt là đơn vị được điều khiển, thay vì mọi chất lỏng phải đi qua một mạng ống cố định.

Giọt có thể đóng vai trò một phần mẫu hoặc một thể tích phản ứng. Nếu vận chuyển, nhập và chia được theo chương trình, thiết bị có khả năng tổ chức nhiều thao tác hóa học trên một bề mặt nhỏ.

Tuy vậy, bản trình diễn chuyển giọt không tự là một hệ phân tích hoàn chỉnh. Nó phải tiếp tục giải các vấn đề về bay hơi, bám dính, tính tương thích và cách đọc kết quả trong mỗi ứng dụng.`],
 ['Điện thế làm đổi năng lượng tại vùng tiếp xúc',`Trong electrowetting trên điện môi, điện trường tác động lên hệ chất lỏng–lớp cách điện–điện cực, làm thay đổi điều kiện năng lượng biểu hiện qua góc tiếp xúc. Nếu phía trước giọt được làm ướt thuận lợi hơn, sự bất đối xứng có thể khiến giọt dịch chuyển.

Cách mô tả “điều khiển sức căng” là một lối nói gọn; cấu trúc điện môi và năng lượng điện dung là phần quan trọng. Không nên hình dung điện trường đơn giản kéo mọi phân tử nước như những hạt mang cùng điện tích.

Góc tiếp xúc có thể bão hòa khi tăng điện thế, và điện tích bị giữ trong lớp cách điện có thể làm đáp ứng không trở lại hoàn toàn. Nghiên cứu năm 1999 về electrowetting thuận nghịch khảo sát chính sự giữ điện tích và độ trễ, cho thấy chất lượng bề mặt là một biến chức năng chứ không chỉ lớp bảo vệ.`],
 ['Ứng dụng hôm nay: một thao tác vật lý cần giữ mẫu không đổi ngoài ý muốn',`Vi lưu số được phát triển cho những quy trình cần quản lý các giọt nhỏ. Nó cho khả năng đổi tuyến thao tác linh hoạt hơn một số hệ kênh, nhưng mỗi mẫu có thành phần riêng có thể làm bề mặt bẩn hoặc thay độ dẫn. Mẫu protein và mẫu dung dịch muối đơn giản không nhất thiết vận chuyển giống nhau.

Độ lặp lại của thể tích sau chia giọt ảnh hưởng trực tiếp đến định lượng. Khi dùng cho phản ứng, còn phải kiểm tra nhiệt và mức trao đổi với môi trường. Một chuyển động nhìn mượt chưa chứng minh lượng chất đã được chuyển chính xác.

Câu chuyện giọt bước trên điện cực cho thấy bề mặt có thể trở thành một cơ cấu vận hành. Hóa học lớp phủ và thiết kế điện phối hợp để thay nơi chất lỏng muốn nằm. Khi kiểm soát được sự thuận nghịch và sai lệch, các giọt không chỉ là vật thể được trình diễn trên video; chúng trở thành những phần của quy trình phân tích có thể lập trình và kiểm chứng.`],
 ],sources:[['Pollack, Fair và Shenderov · Điều khiển giọt bằng electrowetting, 2000','https://doi.org/10.1063/1.1308534'],['Nghiên cứu gốc · Electrowetting thuận nghịch và giữ điện tích','https://arxiv.org/abs/cond-mat/9908328']]
},
{
 id:'acoustophoresis-song-am-doi-dong-cho-hat',category:'khainiem',title:'Sóng âm chuyển hạt sang một dòng chất lỏng khác',summary:'Một trường âm đứng trong vi kênh có thể đưa các hạt tới những đường dòng riêng. Thí nghiệm đổi môi trường cho hồng cầu cho thấy tách không nhất thiết cần giữ mẫu trên màng.',tags:['Acoustophoresis','Sóng âm','Vi lưu','Tách hạt'],image:'/assets/library/lab-synthesis.svg',imageAlt:'Minh họa xử lý mẫu; không phải thiết bị dùng lâm sàng',sections:[
 ['Hạt đi sang dòng sạch trong khi hai dòng ít trộn',`Năm 2005, Petersson và cộng sự báo cáo cách dùng lực âm để chuyển hạt lơ lửng từ một môi trường sang môi trường khác trong vi kênh. Nhóm thử với hạt polymer và những thí nghiệm ban đầu dùng hồng cầu trong mẫu nghiên cứu, trong khi chất màu hòa tan chủ yếu theo dòng ban đầu.

Ý tưởng tận dụng dòng tầng: những lớp chất lỏng cạnh nhau không trộn mạnh do xoáy như trong một bình khuấy. Một lực tác động chọn lọc lên hạt có thể đưa chúng qua ranh giới dòng, rồi các cửa ra thu những phần khác nhau.

Đây là nghiên cứu phương pháp xử lý mẫu. Các tỷ lệ thu hồi trong một thiết kế và mẫu cụ thể không tự chứng minh hiệu quả hoặc an toàn cho mọi quy trình xử lý máu.`],
 ['Mật độ và khả năng nén ảnh hưởng đường đi',`Sóng âm đứng tạo những vùng áp suất dao động có cấu trúc theo không gian. Hạt có tính chất khác môi trường chịu lực bức xạ âm, với hướng và độ lớn phụ thuộc độ tương phản âm, kích thước và điều kiện trường.

Các đối tượng không chỉ được phân biệt bằng khối lượng. Mật độ và khả năng nén góp vào đáp ứng, nên lipid và tế bào có thể được đưa tới những vùng khác nhau trong một số cấu hình. Lực cản của dòng chất lỏng cạnh tranh với lực âm, quyết định hạt có đủ thời gian chuyển sang đường dòng cần thiết hay không.

Những dòng chảy thứ cấp do âm và nhiệt cũng cần được kiểm tra. Nếu chỉ quan sát hạt cuối kênh, có thể khó biết cơ chế nào đã chi phối. Thiết kế tốt cần mô hình, theo dõi quỹ đạo và kiểm phân bố mẫu ở các cửa ra.`],
 ['Ứng dụng hôm nay: đánh giá cả thu hồi lẫn trạng thái sau tách',`Các nghiên cứu sau đó khảo sát tác động của tách âm trong thiết bị nhựa lên các chỉ báo của mẫu máu. Việc theo dõi những thông số sau xử lý giúp đánh giá một phần độ tương thích, bên cạnh hiệu suất tách. Thu được nhiều tế bào chưa đủ nếu cấu trúc hoặc chức năng của chúng bị thay đổi không phù hợp.

Acoustofluidics được nghiên cứu cho tập trung, rửa và phân loại nhiều loại hạt. Cấu hình cần được điều chỉnh theo mẫu, nồng độ và mục đích. Một thí nghiệm trên huyền phù loãng không tự dự đoán hệ có nhiều tương tác tế bào–tế bào.

Câu chuyện dòng sạch cho thấy phân tách có thể diễn ra bằng cách thay đường đi thay vì bắt rồi nhả trên một vật liệu lọc. Chất lỏng và hạt cùng ở trong kênh, nhưng chúng không nhất thiết nhận cùng lực. Khi khai thác đúng khác biệt ấy, sóng âm trở thành một bộ phận của phép phân tích, nối tính chất vật liệu ở cấp nhỏ với việc thu được những phần mẫu có thể sử dụng tiếp.`],
 ],sources:[['Petersson và cộng sự · Chuyển hạt giữa hai môi trường, 2005','https://doi.org/10.1021/ac048394q'],['Nghiên cứu gốc · Đánh giá mẫu sau tách âm','https://pmc.ncbi.nlm.nih.gov/articles/PMC5947325/']]
},
{
 id:'thermophoresis-phan-tu-di-trong-gradient-nhiet',category:'khainiem',title:'Một vùng ấm nhỏ giúp hỏi hai phân tử có gắn nhau không',summary:'Microscale thermophoresis đo thay đổi phân bố khi có gradient nhiệt. Kích thước, điện tích và lớp hydrat hóa cùng góp vào tín hiệu tương tác.',tags:['MST','Thermophoresis','Ái lực','Protein'],image:spectro,imageAlt:'Minh họa đọc tín hiệu quang; không phải cấu hình thiết bị MST',sections:[
 ['Một phép gắn được thử trong môi trường phức tạp hơn đệm',`Năm 2010, Wienken và cộng sự giới thiệu microscale thermophoresis để khảo sát tương tác protein và phân tử nhỏ trong những môi trường như huyết thanh hoặc dịch tế bào. Nhóm dùng các hệ kiểm chứng, gồm calmodulin gắn calcium, rồi so tương tác của quercetin với kinase PKA trong đệm và huyết thanh.

Kết quả trong hai nền khác nhau cho thấy một phép đo trong dung dịch đơn giản chưa luôn đại diện cho môi trường phức tạp. Các thành phần cạnh tranh và tương tác nền có thể làm ái lực biểu kiến thay đổi.

MST không cần cố định mọi đối tác lên một bề mặt như một số phương pháp khác. Đổi lại, nó phải kiểm tra cách nền mẫu và tín hiệu quang ảnh hưởng đến phép suy tương tác.`],
 ['Nhiệt tạo một phân bố có thông tin về bề mặt phân tử',`Gradient nhiệt có thể làm các phân tử phân bố lại, một hiện tượng gọi là thermophoresis. Đáp ứng phụ thuộc kích thước, điện tích và môi trường hydrat hóa, nên khi hai đối tác gắn nhau, sự thay đổi của phức có thể tạo khác biệt đo được.

Một nguồn hồng ngoại thường tạo vùng nóng nhỏ và tín hiệu huỳnh quang theo dõi phân bố của thành phần quan tâm. Cần phân biệt thay đổi nhanh của huỳnh quang theo nhiệt với chuyển động chậm hơn của các phân tử. Những phần này có thể đều mang thông tin nhưng không nên gộp mà không có mô hình.

Chất thử có thể tự phát sáng, làm tắt nhãn hoặc gây kết tụ. Những kiểm tra tín hiệu ban đầu và mẫu đối chứng giúp nhận ra các trường hợp mà một đường cong chuẩn độ đẹp không thực sự phản ánh gắn chọn lọc.`],
 ['Ứng dụng hôm nay: một phép đo bổ sung trong bộ công cụ tương tác',`Năm 2012, Seidel và cộng sự trình bày MST không cần nhãn ngoài trong những hệ dùng huỳnh quang nội sinh phù hợp. Nhóm khảo sát nhiều loại tương tác, từ ion tới protein, cho thấy có thể điều chỉnh cách đọc theo đối tượng.

Kết quả ái lực cần gắn với nồng độ, môi trường và mô hình. Nếu có nhiều vị trí hoặc đối tác đa hóa trị, một hằng số đơn giản có thể chỉ là giá trị biểu kiến. Đối chiếu với những kỹ thuật khác giúp xác nhận phần cơ chế mà MST đang báo.

Câu chuyện vùng ấm nhỏ làm rõ rằng chuyển động trong dung dịch có thể phản ánh hóa học bề mặt. Phân tử không cần đổi khối lượng rất lớn mới tạo tín hiệu; việc lớp nước và điện tích quanh nó thay đổi cũng có thể quan trọng. Khi được kiểm soát, độ nhạy ấy giúp nghiên cứu tương tác trong những mẫu phức tạp hơn, đồng thời nhắc rằng chính nền mẫu cũng là một phần của câu trả lời.`],
 ],sources:[['Wienken và cộng sự · MST trong dịch sinh học, 2010','https://www.nature.com/articles/ncomms1093'],['Seidel và cộng sự · MST không nhãn ngoài, 2012','https://pubmed.ncbi.nlm.nih.gov/23001866/']]
},
{
 id:'tga-can-mau-trong-luc-no-doi-chat',category:'khainiem',title:'Cân một mẫu trong lúc nó mất nước rồi đổi thành chất khác',summary:'Calcium oxalate monohydrate tạo những bậc mất khối lượng giúp kiểm tra TGA. Mỗi bậc cần được nối với phản ứng và sản phẩm khí, không chỉ đọc nhiệt độ trên đồ thị.',tags:['TGA','Calcium oxalate','Phân tích nhiệt'],image:'/assets/library/apparatus-calorimeter.svg',imageAlt:'Minh họa phân tích nhiệt; không phải sơ đồ lò hoặc dữ liệu TGA cụ thể',sections:[
 ['Một chất chuẩn tạo nhiều bậc để kiểm máy',`Tài liệu đào tạo NIST dùng calcium oxalate monohydrate làm ví dụ cho phân tích nhiệt khối lượng. Khi gia nhiệt trong điều kiện phù hợp, mẫu trải qua mất nước, chuyển oxalate thành carbonate rồi carbonate thành oxide. Các phần khối lượng tương ứng có thể được tính từ thành phần lý tưởng để kiểm tra phép đo.

Một chất chuẩn thương mại của Elemental Microanalysis cũng được cung cấp cho kiểm tra mất khối lượng TGA, kèm thông tin độ tinh khiết và phạm vi sử dụng. Chứng chỉ không thay cho việc xác nhận chất còn phù hợp sau lưu trữ và mở lọ.

Giá trị của mẫu không chỉ là có một nhiệt độ phân hủy nổi tiếng. Nó tạo nhiều đoạn trong đường cân, giúp kiểm xem hệ có theo dõi đúng sự thay đổi tương đối của khối lượng hay không.`],
 ['Đường cân cho biết vật chất rời mẫu, chưa tự nói đó là gì',`TGA ghi khối lượng khi nhiệt độ hoặc thời gian thay đổi theo chương trình. Một bước giảm có thể do nước, dung môi hoặc sản phẩm phân hủy thoát ra. Một bước tăng có thể liên quan đến hấp thu hoặc phản ứng với khí nền.

Với chất đơn giản đã biết, tính lượng và cơ chế giúp gán các bậc. Trong hỗn hợp thực, nhiều quá trình có thể chồng lên nhau, nên nhiệt độ một đỉnh đạo hàm không phải căn cước tuyệt đối của chất. Ghép với FTIR hoặc khối phổ của khí thoát ra có thể bổ sung nhận diện.

Tốc độ gia nhiệt, lượng mẫu, dòng khí và hình học chén ảnh hưởng đường chuyển hóa và truyền nhiệt. Vì vậy, một giá trị nhiệt độ trong chứng chỉ không nên được áp như hằng số không phụ thuộc phương pháp. Cần phân biệt tỷ lệ khối lượng lý thuyết với nhiệt độ quan sát trong cấu hình cụ thể.`],
 ['Ứng dụng hôm nay: từ độ ẩm tới thành phần và độ bền nhiệt',`TGA được dùng trong nghiên cứu polymer, vật liệu vô cơ và composite để khảo sát mất chất bay hơi, mức cặn hoặc các biến đổi nhiệt. Một mẫu composite có thể để lại phần khoáng sau khi nền hữu cơ chuyển hóa, nhưng muốn định lượng cần biết các phản ứng của từng phần trong khí đang dùng.

NIST lưu ý với calcium oxalate hydrate rằng lượng nước thực có thể lệch khỏi tỷ lệ lý tưởng và nên được kiểm độc lập khi cần. Điều này cho thấy ngay một ví dụ chuẩn cũng cần đo thành phần, không chỉ tin công thức trên nhãn.

Câu chuyện chiếc cân trong lò nối bảo toàn khối lượng với động học. Vật liệu không chỉ nóng lên; nó có thể tạo những chất mới và mất các phần khác nhau ra môi trường. Đường cong hữu ích khi mỗi đoạn được đặt trong một giả thuyết hóa học có thể kiểm tra. Khi đó, phần khối lượng còn lại trở thành bằng chứng về những gì mẫu đã trải qua.`],
 ],sources:[['NIST · Ví dụ calcium oxalate trong phân tích nhiệt khối lượng','https://www.govinfo.gov/content/pkg/GOVPUB-C13-ba9af1ebc9ae9b72438ceba8e9c7b9f6/pdf/GOVPUB-C13-ba9af1ebc9ae9b72438ceba8e9c7b9f6.pdf'],['Elemental Microanalysis · Chứng chỉ chuẩn calcium oxalate','https://www.elementalmicroanalysis.com/Downloads/B2350-S06D020.pdf']]
},

{
 id:'dma-cao-su-tra-nang-luong-khac-nhip',category:'khainiem',title:'Cao su trả lại bao nhiêu năng lượng sau mỗi lần biến dạng?',summary:'DMA đo phần đàn hồi và phần tiêu tán theo nhịp tác động. Nghiên cứu gai lốp dùng dữ liệu này để cân nhắc bám đường và tổn thất khi lăn.',tags:['DMA','Nhớt–đàn hồi','Cao su','Lốp'],image:polymer,imageAlt:'Minh họa chuỗi polymer; không phải cấu trúc đầy đủ của cao su gai lốp',sections:[
 ['Một vật liệu cần bám nhưng không nên biến quá nhiều năng lượng thành nhiệt',`Trong nghiên cứu cao su gai lốp gia cường silica tại Đại học Twente, các nhà nghiên cứu thêm những nhựa oligomer khác nhau và đo đáp ứng cơ động. Các chất bổ sung làm thay đổi vùng chuyển thủy tinh và tương tác trong hệ, qua đó tác động đến những chỉ báo liên quan đến bám ướt và cản lăn.

Lốp liên tục biến dạng khi đi qua vùng tiếp xúc với mặt đường. Một phần năng lượng được trả lại, phần khác bị tiêu tán. Nhưng khả năng bám cũng cần tương tác cơ học phù hợp trên nhiều thang thời gian, nên không thể chỉ yêu cầu mọi tổn hao càng nhỏ càng tốt.

DMA cung cấp một cách khảo sát có kiểm soát trước khi đưa vật liệu vào các phép thử lốp phức tạp hơn.`],
 ['Tín hiệu lực và biến dạng không luôn cùng pha',`Trong phép đo cơ động nhỏ, mẫu chịu dao động và đáp ứng được phân tích thành phần lưu trữ năng lượng cùng phần tổn hao. Tỷ số thường biểu diễn bằng tan δ cho biết mức lệch pha trong mô hình. Giá trị thay đổi theo tần số và nhiệt độ vì các đoạn chuỗi và cấu trúc có những thời gian đáp ứng khác nhau.

Một đỉnh gần vùng chuyển thủy tinh không chỉ là nhiệt độ nóng chảy. Nó phản ánh sự thay đổi linh động trên thang thời gian đo. Đổi tần số có thể làm vị trí đặc trưng dịch, nên so số liệu phải giữ điều kiện tương ứng.

Chất độn tạo thêm mạng tương tác và làm đáp ứng phụ thuộc biên độ. Nếu biến dạng quá lớn để ở miền tuyến tính, các thông số có thể không còn có cùng ý nghĩa như trong phép dao động nhỏ. Cấu trúc bị phá rồi hồi phục cũng góp vào tổn hao.`],
 ['Ứng dụng hôm nay: chỉ báo vật liệu cần được nối với phép thử sử dụng',`Các nghiên cứu gai lốp thường dùng tan δ tại những vùng nhiệt độ làm chỉ báo so sánh, nhưng điều đó không biến một điểm DMA thành phép đo trực tiếp mọi điều kiện đường. Tải, tốc độ, mặt đường và cấu trúc lốp đều tham gia hiệu năng thật.

Nghiên cứu năm 2025 về silica và xử lý hydrat hóa tiếp tục phối hợp đặc tính động với các phép đo cơ khác. Việc dùng nhiều chỉ tiêu giúp nhận ra cải tiến ở một phía có làm đổi độ bền hoặc gia công ở phía khác không.

Câu chuyện cao su cho thấy tính chất vật liệu không chỉ là “cứng” hay “mềm”. Nó còn là câu hỏi mẫu đáp lại nhanh tới đâu và giữ hay mất năng lượng theo từng nhịp. Khi các nhịp của phép đo được nối đúng với nhịp công việc, hóa học polymer và chất độn có thể được điều chỉnh có mục tiêu thay vì chỉ thay công thức rồi chờ một kết quả tốt hơn.`],
 ],sources:[['Twente · Nhựa oligomer trong gai lốp silica','https://ris.utwente.nl/ws/files/5520187/56_N%20Vleugels.pdf'],['Nghiên cứu gốc · Tối ưu tính cơ động cao su gai lốp, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC11945894/']]
},
{
 id:'nanoindentation-dau-an-nho-ke-do-cung',category:'khainiem',title:'Một dấu ấn rất nhỏ giúp đo độ cứng và cách vật liệu hồi lại',summary:'Phương pháp Oliver–Pharr dùng đường tải–độ sâu để suy tính cơ học. Hình dạng đầu ấn và diện tích tiếp xúc là phần thiết yếu của phép đo.',tags:['Nanoindentation','Độ cứng','Môđun đàn hồi'],image:'/assets/library/crystal-diamond.svg',imageAlt:'Minh họa mạng kim cương; không phải hình học chính xác của đầu ấn Berkovich',sections:[
 ['Không chỉ đo vết lõm còn lại sau khi nhấc đầu ấn',`Năm 1992, Oliver và Pharr khảo sát đường tải–độ sâu của sáu vật liệu bằng đầu ấn Berkovich. Họ xây phương pháp xác định độ cứng và môđun từ dữ liệu tăng tải rồi dỡ tải, thay vì chỉ đo hình vết lõm sau cùng. Đường dỡ tải không hoàn toàn tuyến tính ngay ở đoạn đầu, nên cách khớp cần phản ánh cơ học tiếp xúc phù hợp hơn.

Công cụ này đặc biệt hữu ích với các vùng nhỏ hoặc màng mà phép kéo mẫu lớn không thuận tiện. Nhưng thu nhỏ phép ấn làm độ nhám và trạng thái đầu ấn trở thành những yếu tố đáng kể.

Một vết lõm nhìn giống nhau có thể được tạo qua những lịch sử lực khác nhau; ghi cả đường đi cung cấp thêm thông tin về đàn hồi và biến dạng không hồi phục.`],
 ['Độ cứng cần diện tích, môđun cần độ cứng tiếp xúc',`Độ cứng ấn được liên hệ với tải chia cho diện tích tiếp xúc thích hợp. Độ dốc ban đầu khi dỡ tải cung cấp độ cứng tiếp xúc, từ đó suy môđun quy đổi có tính cả biến dạng của đầu ấn. Không thể xem đầu kim cương là hoàn toàn không biến dạng trong mọi phân tích chính xác.

Diện tích không phải lúc nào bằng diện tích vết nhìn sau khi mẫu hồi phục. Vật liệu có thể vun lên hoặc lún quanh đầu ấn, làm mô hình đơn giản sai. Hàm diện tích của đầu cần được hiệu chuẩn vì đỉnh không hoàn hảo hình học, nhất là ở độ sâu rất nhỏ.

Màng trên nền còn tạo một hệ composite cơ học: ấn sâu hơn có thể đọc ngày càng nhiều phần nền. Độ trôi nhiệt và độ mềm của khung máy cũng phải được tách khỏi chuyển động của mẫu.`],
 ['Ứng dụng hôm nay: một phép đo cục bộ có miền áp dụng',`Trong tổng kết năm 2004, Oliver và Pharr cập nhật những cải tiến và giới hạn của phương pháp sau hơn một thập niên sử dụng rộng. Việc một thuật toán trở thành chuẩn thực hành không có nghĩa mọi vật liệu mềm, xốp hoặc phụ thuộc thời gian đều đáp ứng các giả định ban đầu.

Nanoindentation được dùng để khảo sát lớp phủ, pha vật liệu và những vùng có kích thước nhỏ. Khi mẫu không đồng nhất, nhiều vị trí cần được đo để hiểu phân bố thay vì chọn một dấu ấn đẹp nhất.

Câu chuyện cho thấy phép đo cơ học cũng cần hóa học cấu trúc: pha, thành phần, lịch sử gia công và bề mặt cùng ảnh hưởng đáp ứng. Đầu ấn không chỉ hỏi vật cứng đến đâu; nó đặt một bài toán tiếp xúc cụ thể lên mẫu. Kết quả có giá trị khi người đọc biết hình học, thang tải và phần mô hình đã dùng để chuyển một đường cong thành thuộc tính vật liệu.`],
 ],sources:[['Oliver và Pharr · Phương pháp ấn có đo tải và độ sâu, 1992','https://web.mit.edu/cortiz/www/3.052/3.052CourseReader/45_OliverPharr1992Nanoindentation.pdf'],['Oliver và Pharr · Cải tiến và giới hạn, 2004','https://doi.org/10.1557/jmr.2004.19.1.3']]
},
{
 id:'yield-stress-kem-danh-rang-giu-dang',category:'khainiem',title:'Kem đánh răng đứng trên bàn chải nhưng vẫn chảy khi bóp',summary:'Ứng suất chảy mô tả một chuyển tiếp hữu ích trong vật liệu dạng paste. Các phép thử kem đánh răng cho thấy thời gian và lịch sử cắt cũng quyết định đáp ứng.',tags:['Ứng suất chảy','Paste','Lưu biến','Kem đánh răng'],image:polymer,imageAlt:'Minh họa mạng vật liệu mềm; không phải công thức kem đánh răng',sections:[
 ['Một sản phẩm phải nhận hai nhiệm vụ có vẻ trái nhau',`Nghiên cứu năm 2011 dùng kem đánh răng thương mại làm mẫu paste để khảo sát dòng qua các khuôn đùn khác nhau. Vật liệu cần ra khỏi tuýp khi chịu lực, nhưng sau đó giữ được hình tương đối ổn định trên bàn chải. Hai yêu cầu này không thể được mô tả chỉ bằng một độ nhớt cố định như với chất lỏng Newton đơn giản.

Kem đánh răng là hệ nhiều thành phần, gồm chất rắn phân tán và nền lỏng–polymer tạo cấu trúc. Những tương tác làm hệ chống biến dạng ở tải thấp, nhưng cấu trúc có thể tái sắp xếp khi lực đủ lớn.

Thí nghiệm đùn đặt câu hỏi gần với gia công và sử dụng, bổ sung cho những đường đo trong rheometer có hình học khác.`],
 ['Một ngưỡng hữu ích nhưng phụ thuộc cách hỏi',`Ứng suất chảy thường được dùng để mô tả mức tác động trước khi dòng đáng kể xuất hiện trong một mô hình. Tuy nhiên, vật liệu có thể biến dạng chậm dưới tải trong thời gian dài, và kết quả suy ngưỡng phụ thuộc thời gian quan sát cùng lịch sử chuẩn bị.

Nếu mẫu đã bị khuấy hoặc cắt mạnh, cấu trúc có thể chưa hồi phục như trạng thái nghỉ lâu. Trượt ở thành cũng có thể khiến máy ghi chuyển động mà phần khối bên trong ít biến dạng. Chọn bề mặt đo và kiểm các hình học giúp phân biệt những hiện tượng này.

Một đường mô hình Bingham hoặc Herschel–Bulkley có thể mô tả miền dữ liệu, nhưng các tham số không tự là đặc tính bất biến của mọi chế độ vận hành. Cần nêu nhiệt độ, khoảng tốc độ và cách đưa mẫu tới trạng thái bắt đầu.`],
 ['Ứng dụng hôm nay: nối máy đo với cảm giác và tính năng',`Nghiên cứu năm 2026 trên mười lăm công thức kem đánh răng kết hợp ứng suất chảy, lưu biến bọt và phân tích cấu trúc bọt để dự đoán một phần cảm nhận của người dùng. Kết quả là mô hình trong tập công thức được khảo sát, không phải thước đo phổ quát thay thế mọi đánh giá sử dụng.

Vật liệu còn phải được kiểm về phân phối từ bao bì, ổn định và những chức năng riêng của sản phẩm. Độ đứng dáng tốt không tự chứng minh khả năng làm sạch hoặc tính phù hợp sức khỏe.

Câu chuyện paste làm rõ vì sao vật liệu mềm không luôn thuộc hẳn một phía rắn hoặc lỏng. Cách nó đáp lại phụ thuộc lực và thời gian. Hóa học công thức xây một mạng đủ bền để giữ dạng nhưng đủ linh động để sử dụng, rồi lưu biến cung cấp ngôn ngữ đo phần cân bằng ấy. Một vệt kem nhỏ trên bàn chải là kết quả của nhiều tương tác vi mô được tổ chức cho hai giai đoạn công việc khác nhau.`],
 ],sources:[['Nghiên cứu gốc · Kem đánh răng qua khuôn đùn, 2011','https://www.sciencedirect.com/science/article/pii/S0377025711001972'],['Nghiên cứu gốc · Lưu biến và cảm nhận bọt kem đánh răng, 2026','https://doi.org/10.1111/jtxs.70110']]
},
{
 id:'thixotropy-son-chay-deu-roi-dung-lai',category:'khainiem',title:'Sơn cần chảy đủ lâu để phẳng, rồi dừng trước khi chảy xệ',summary:'Thixotropy mô tả sự suy giảm và hồi phục cấu trúc theo lịch sử cắt. Phép thử ba giai đoạn giúp nối dữ liệu với lúc quét sơn và lúc lớp sơn nghỉ.',tags:['Thixotropy','Sơn','Hồi phục','Lưu biến'],image:polymer,imageAlt:'Minh họa mạng tương tác trong vật liệu; không phải cấu trúc một loại sơn thương mại',sections:[
 ['Hai lỗi có thể xuất hiện ở hai phía của cùng một lựa chọn',`Năm 2016, Bhavsar và Shreepathi khảo sát mười ba loại sơn latex gốc nước bằng phép thử vòng trễ và thử thixotropy ba giai đoạn. Họ tìm các chỉ báo liên quan tới khả năng tự san phẳng và chống chảy xệ. Một lớp sơn phải còn linh động đủ để xóa dấu chổi nhưng không được tiếp tục chảy dưới trọng lực quá lâu.

Chất làm đặc nền cellulose và loại HEUR cần được xét riêng trong nghiên cứu. Cùng một độ nhớt ở một tốc độ cắt không đủ bảo đảm cùng hành vi sau khi sơn rời chổi.

Điều này cho thấy công thức được thiết kế theo một hành trình, không chỉ theo một trạng thái trong lon.`],
 ['Lịch sử tác động làm cấu trúc bên trong đổi',`Thixotropy thường mô tả sự giảm độ nhớt theo thời gian dưới cắt và khả năng hồi phục khi giảm hoặc bỏ cắt. Các tương tác hoặc mạng tạm thời bị phá và tái tạo, nên đáp ứng phụ thuộc cả mức tác động lẫn thời gian.

Nó cần được phân biệt với shear thinning tức thời, nơi độ nhớt thay đổi theo tốc độ nhưng không nhất thiết có cùng lịch sử hồi phục. Tính nhớt–đàn hồi cũng có thể tạo trễ, nên một vòng đi–về không tự chứng minh một cơ chế duy nhất.

Trong thử ba giai đoạn, mẫu được đo ở trạng thái nghỉ nhẹ, chịu cắt mạnh mô phỏng thao tác rồi trở lại điều kiện nhẹ để theo dõi hồi phục. Những khoảng thời gian phải được chọn theo câu hỏi sử dụng. Một tỷ lệ hồi phục sau vài giây không thay thế dữ liệu sau nhiều phút nếu công việc yêu cầu khoảng dài hơn.`],
 ['Ứng dụng hôm nay: điều chỉnh tương tác thay vì chỉ thêm độ đặc',`Nghiên cứu năm 2024 về chất làm đặc HEUR kết hợp cấu trúc phân tử với mô phỏng để khảo sát lưu biến lớp phủ. Các đầu kỵ nước và đoạn polymer tạo mạng liên kết tạm thời với môi trường, nên kiến trúc phân tử có thể thay đổi cả độ nhớt lẫn cách hồi phục.

Ứng dụng còn phải xét bay hơi và đóng màng. Một phép thử trong rheometer không mô phỏng đầy đủ mặt tường đang khô, nên dữ liệu cần được đối chiếu với phép thử lớp phủ thực. Những giới hạn kinh nghiệm tìm được cho một họ sơn không nên được áp cho mọi hệ.

Câu chuyện sơn cho thấy thời gian là một thành phần thiết kế. Người dùng muốn vật liệu dễ trải ở một khoảnh khắc và đứng yên ở khoảnh khắc tiếp theo. Hóa học tạo các tương tác có thể thay đổi dưới lực, còn phép đo theo lịch sử giúp kiểm xem chúng đổi đúng nhịp hay không. Một lớp sơn phẳng là kết quả của sự phối hợp giữa dòng chảy, hồi phục và quá trình mất dung môi.`],
 ],sources:[['Bhavsar và Shreepathi · Sơn gốc nước và thử ba giai đoạn, 2016','https://doi.org/10.1016/j.porgcoat.2016.07.016'],['Nghiên cứu gốc · Kiến trúc HEUR và lưu biến sơn, 2024','https://pubs.acs.org/iecred/article/63/22/10009/862346/Tailoring-Waterborne-Coating-Rheology-with']]
},

{
 id:'bot-bap-va-cham-mat-tran-ket-cung',category:'khainiem',title:'Bột bắp gặp va chạm: một vùng cứng tạm thời lan ra',summary:'Huyền phù đậm đặc có thể chống một tác động nhanh theo cách khác với phép cắt ổn định. Ảnh tốc độ cao và tia X giúp theo dõi mặt trước của vùng kẹt hạt.',tags:['Huyền phù','Jamming động','Va chạm'],image:'/assets/library/organic-carbohydrate.svg',imageAlt:'Minh họa carbohydrate; không phải ảnh huyền phù hoặc phép thử va chạm',sections:[
 ['Một thanh kim loại làm lộ điều phép khuấy chưa kể hết',`Năm 2012, Waitukaitis và Jaeger dùng ảnh tốc độ cao, cảm biến lực và tia X để khảo sát một thanh kim loại va vào huyền phù bột bắp trong nước. Họ theo dõi một vùng kẹt hạt phát triển dưới điểm tác động, hấp thu động lượng và tạo đáp ứng rất khác chất lỏng loãng.

Những quan sát này giúp phân biệt va chạm nhanh với hiện tượng đặc lên trong phép cắt ổn định. Các mô hình giải thích độ nhớt dưới cắt không tự đủ để mô tả ứng suất pháp rất lớn trong một tác động cục bộ.

Sự thay đổi diễn ra theo thời gian và phụ thuộc độ dày lớp mẫu. Vật liệu không bỗng biến thành một chất rắn hóa học mới đồng đều khắp cốc.`],
 ['Các hạt mất khả năng đi vòng qua nhau trong vùng chịu tải',`Ở huyền phù đậm đặc, khoảng trống để các hạt tái sắp xếp bị hạn chế. Tác động nhanh có thể tạo một mạng tiếp xúc truyền lực và một mặt trước lan vào phần chưa bị tác động. Những biên của hệ ảnh hưởng cách lực được truyền và mức đáp ứng cuối.

Nước vẫn có vai trò trong bôi trơn, truyền áp và vận chuyển, nhưng không nên coi quá trình chỉ là nước “đặc hơn”. Tính chất của cả pha hạt, nồng độ và điều kiện giam giữ quyết định hệ có đi vào miền kẹt như thế nào.

Khi bỏ tác động, hệ có thể trở về trạng thái dễ chảy hơn. Điều này khác đóng rắn cộng hóa trị của nhựa. Cấu trúc chịu lực là một trạng thái động của các hạt, không phải sản phẩm phản ứng mới được tạo vĩnh viễn.`],
 ['Ứng dụng hôm nay: muốn chống va chạm phải thử đúng kiểu tải',`Các huyền phù đặc lên được nghiên cứu cho vật liệu hấp thu năng lượng và nhiều hệ cơ học. Nhưng một mẫu cản tốt thanh va đập trong phòng thí nghiệm chưa tự chứng minh tính năng bảo vệ của sản phẩm hoàn chỉnh. Vỏ chứa, chiều dày, nhiệt độ và kiểu tác động đều cần được xét.

Những nghiên cứu này cung cấp cách đo và mô hình để hỏi quá trình tạo vùng chịu lực diễn ra nhanh đến đâu. Dữ liệu theo thời gian quan trọng vì cùng vật liệu có thể nhận công việc rất khác dưới tác động chậm và nhanh.

Câu chuyện bột bắp cho thấy một khái niệm vật liệu cần gắn với cách thử. Gọi một hệ là “phi Newton” chỉ mở đầu, chưa mô tả cơ chế hoặc hiệu năng. Khi nhìn được mặt trước kẹt hạt lan ra, người nghiên cứu có thể nối một hiệu ứng gây ngạc nhiên với những đại lượng đo được: tốc độ lan, lực và động lượng. Chính bước đó biến một màn trình diễn thành hiểu biết có thể dùng cho thiết kế.`],
 ],sources:[['Waitukaitis và Jaeger · Mặt trước jamming động, 2012','https://pubmed.ncbi.nlm.nih.gov/22785316/'],['Báo cáo thực nghiệm · Đáp ứng của huyền phù dưới tác động','https://research-explorer.ista.ac.at/record/114']]
},
{
 id:'inkjet-chuoi-polymer-keo-duoi-giot',category:'khainiem',title:'Một chút polymer có thể giữ đuôi giọt mực khỏi vỡ thành giọt phụ',summary:'Lưu biến kéo giãn quyết định cách sợi lỏng co và đứt trong in phun. Độ nhớt cắt thấp một mình chưa đủ để chọn mực.',tags:['Lưu biến kéo giãn','In phun','Giọt','Polymer'],image:polymer,imageAlt:'Minh họa chuỗi polymer; không phải ảnh đầu phun hoặc giọt mực cụ thể',sections:[
 ['Một giọt mong muốn có thể kéo theo nhiều giọt nhỏ',`Nghiên cứu năm 2014 ghi hình ở tốc độ rất cao các dung dịch polystyrene được phun từ đầu in. Nhóm theo dõi sợi lỏng phía sau giọt, thời điểm tách khỏi vòi và sự hình thành những hạt nhỏ phụ. Các dung dịch có độ nhớt cắt thấp tương tự vẫn có thể phun khác vì độ đàn hồi và đáp ứng kéo giãn khác.

Trong in, giọt phụ có thể đi lệch hoặc tạo vệt ngoài vị trí mong muốn. Vì thế, câu hỏi không chỉ là mực có chảy qua vòi được hay không, mà là dòng chất lỏng kết thúc thành một hay nhiều giọt theo quỹ đạo nào.

Một tính chất được đo trong máy quay cắt chậm chưa mô tả toàn bộ quá trình giãn rất nhanh ở đầu phun.`],
 ['Chuỗi bị kéo dài rồi cần thời gian hồi lại',`Khi sợi lỏng mỏng dần, trường dòng kéo giãn các chuỗi polymer. Nếu thời gian biến dạng ngắn hơn khả năng thư giãn, chuỗi không kịp trở về trạng thái ban đầu và tạo ứng suất đàn hồi. Ứng suất ấy cạnh tranh với sức căng muốn co mặt lỏng.

Nồng độ, chiều dài chuỗi và chất lượng dung môi ảnh hưởng mức đáp ứng. Thêm polymer có thể làm giảm giọt phụ trong một miền, nhưng quá nhiều có thể cản phun hoặc giữ sợi kéo dài không phù hợp. Không có quy tắc rằng mực càng đàn hồi càng tốt.

Nghiên cứu mô hình năm 2012 phân biệt các chế độ theo độ kéo chuỗi và thời gian thư giãn. Những miền khác nhau có thể bị giới hạn bởi độ nhớt, đàn hồi hoặc độ nhớt kéo giãn ở biến dạng lớn. Cần biết hệ đang ở miền nào trước khi dùng một tham số để dự đoán.`],
 ['Ứng dụng hôm nay: tối ưu giọt bằng phép đo đúng thời gian',`Nghiên cứu năm 2021 về các sợi lỏng mảnh cho thấy dung dịch PEO rất loãng có thể ngăn giọt vệ tinh trong những điều kiện khảo sát. Tốc độ co của sợi còn có thể vượt một dự đoán thuần quán tính–mao dẫn do ứng suất đàn hồi đã tích lại.

Các kết quả hỗ trợ thiết kế mực polymer và vật liệu in chức năng, nhưng cần được thử với đầu phun và thành phần thực. Hạt rắn, chất hoạt động bề mặt và bay hơi có thể thêm những con đường thay đổi khác.

Câu chuyện đuôi giọt cho thấy cấu trúc phân tử ảnh hưởng một sự kiện chỉ kéo dài rất ngắn. Chuỗi polymer không chỉ làm chất lỏng “đặc”; nó mang trí nhớ cơ học trong một khoảng thời gian. Khi khoảng ấy tương ứng với nhịp đầu phun, một lượng nhỏ thành phần có thể quyết định giọt về đúng chỗ hay chia thành những dấu không mong muốn trên bề mặt in.`],
 ],sources:[['Nghiên cứu gốc · In phun dung dịch polymer đàn hồi yếu, 2014','https://www.sciencedirect.com/science/article/pii/S0377025714000135'],['Nghiên cứu mô hình · Các chế độ phun polymer, 2012','https://doi.org/10.1122/1.4724331'],['Nghiên cứu gốc · Co sợi lỏng nhớt–đàn hồi, 2021','https://arxiv.org/abs/2102.08876']]
},
{
 id:'jamming-tui-hat-tro-thanh-tay-gap',category:'khainiem',title:'Túi hạt mềm ôm vật rồi cứng lên thành tay gắp',summary:'Một thay đổi nhỏ trong đóng gói hạt giúp bộ gắp thích nghi với nhiều hình dạng. Ma sát, hút và khóa hình học cùng quyết định lực giữ.',tags:['Jamming','Hạt rời','Robot mềm','Ma sát'],image:'/assets/library/earth-minerals.svg',imageAlt:'Minh họa vật liệu hạt; không phải ảnh hoặc bản thiết kế bộ gắp',sections:[
 ['Một bàn tay không cần ngón cứng định hình trước',`Năm 2010, Brown và cộng sự công bố bộ gắp dùng một màng đàn hồi chứa vật liệu hạt. Khi còn mềm, túi ôm theo vật; khi giảm áp bên trong, các hạt bị ép chặt và cấu trúc trở nên cứng hơn. Nhóm thử nhiều vật có hình dạng khác nhau để xem thiết kế thích nghi tới đâu.

Công trình ghi nhận chỉ một thay đổi rất nhỏ về thể tích đóng gói đã đủ tạo khác biệt lớn về khả năng giữ. Ý tưởng chuyển phần phức tạp từ nhiều khớp cơ khí sang trạng thái của vật liệu bên trong màng.

Tuy vậy, gọi là bộ gắp “phổ dụng” trong tên nghiên cứu không có nghĩa nó cầm được mọi vật hoặc giữ cùng lực trong mọi cấu hình.`],
 ['Hạt riêng rẽ tạo một mạng truyền lực',`Ở trạng thái lỏng hạt, các phần tử có thể sắp xếp lại khi túi áp lên vật. Khi bị giam chặt hơn, mạng tiếp xúc và ma sát hạn chế chuyển động tương đối, tạo trạng thái jamming. Vật liệu không phải được nung chảy rồi đông hoặc nối bằng phản ứng hóa học mới.

Lực giữ có thể đến từ ma sát, chênh lệch áp suất khi có kín khí và sự khóa hình học khi túi ôm qua những phần thích hợp. Các cơ chế không luôn đóng góp bằng nhau. Một vật trơn, có lỗ hoặc hình dạng khác có thể làm một cơ chế mất tác dụng.

Độ mềm và độ dày màng cũng quan trọng. Nếu chỉ thay hạt mà bỏ phần màng và cách tiếp xúc, khó hiểu vì sao hiệu năng đổi. Bộ gắp là một hệ composite cơ học, không chỉ một cốc hạt được gọi là vật liệu thông minh.`],
 ['Ứng dụng hôm nay: thử lực giữ theo đúng chế độ',`Nghiên cứu năm 2020 so các vật liệu hạt trong miền giữ bằng ma sát, không khóa hình học. Trong phạm vi đó, nhóm nhận thấy lực giữ cực đại không phụ thuộc đơn giản vào loại hạt như trực giác có thể dự đoán. Kết quả giúp tập trung vào những biến thiết kế thật sự chi phối chế độ đang xét.

Bộ gắp hạt được nghiên cứu trong robot mềm và xử lý các vật có hình dạng thay đổi. Tốc độ thao tác, độ lặp lại, độ bền màng và khả năng nhả vật đều cần được kiểm tra, bên cạnh tải lớn nhất.

Câu chuyện này cho thấy chức năng có thể xuất hiện từ cách nhiều hạt quen thuộc cùng bị giam giữ. Không cần mỗi hạt có cơ cấu riêng; một thay đổi áp suất làm mạng tiếp xúc đổi trạng thái. Khi hiểu những cơ chế giữ vật, người thiết kế có thể chọn cấu hình phù hợp thay vì chỉ tăng độ cứng, và dùng chính khả năng mềm trước–cứng sau như một phần của thao tác.`],
 ],sources:[['Brown và cộng sự · Bộ gắp hạt, 2010','https://pmc.ncbi.nlm.nih.gov/articles/PMC2973877/'],['Nghiên cứu gốc · Ảnh hưởng vật liệu hạt lên lực giữ','https://arxiv.org/abs/2010.14992']]
},
{
 id:'frost-heave-nuoc-di-ve-thau-kinh-bang',category:'khainiem',title:'Đất đội lên không chỉ vì nước có sẵn nở ra khi đông',summary:'Nước có thể di chuyển tới những lớp băng đang phát triển trong đất lạnh. Frost heave là bài toán vận chuyển và chuyển pha, không chỉ một phép tính giãn thể tích.',tags:['Frost heave','Thấu kính băng','Đất','Chuyển pha'],image:'/assets/library/earth-minerals.svg',imageAlt:'Minh họa môi trường khoáng; không phải mặt cắt đất có thấu kính băng',sections:[
 ['Một lớp băng có thể nhận thêm nước từ nơi khác',`Các thí nghiệm kinh điển của Taber từ năm 1929–1930 giúp xác lập rằng đất đội do băng không thể chỉ giải thích bằng sự nở thể tích của nước ban đầu trong lỗ. Nước có thể được kéo tới vùng đang đông và tạo những lớp băng tách biệt, thường gọi là thấu kính băng.

Tổng kết của Peppin và Style năm 2013 đối chiếu nhiều mô hình về cách các lớp ấy hình thành và lớn lên. Câu hỏi quan trọng là nước đi qua những vùng lạnh như thế nào, lực nào thúc đẩy và điều gì giới hạn tốc độ.

Một hiện tượng gây biến dạng nền đường vì vậy liên quan đến những lớp nước rất mỏng ở giao diện, nhỏ hơn nhiều so với vết nứt hoặc gò đất nhìn thấy sau cùng.`],
 ['Dưới nhiệt độ nóng chảy vẫn có thể còn đường cho nước',`Trong môi trường lỗ nhỏ và gần bề mặt, nước có thể tồn tại ở những màng chưa đông dưới nhiệt độ nóng chảy của khối lớn. Độ cong, tương tác bề mặt và chất tan ảnh hưởng điều kiện cân bằng. Gradient nhiệt tạo sự khác nhau về thế hóa học và những lực liên quan, hỗ trợ vận chuyển tới vùng băng phát triển.

Lưu lượng bị giới hạn bởi khả năng đi qua đất và trở lực gần giao diện băng–hạt. Các mô hình không nhất thiết thống nhất về phần chi phối trong mọi loại đất. Độ thấm, tải phía trên và tốc độ làm lạnh cùng quyết định có một lớp băng, nhiều lớp lặp lại hay không đội rõ.

Không thể lấy một ảnh băng trong lỗ để kết luận toàn bộ cơ chế. Cần đo nhiệt độ, chuyển động nước và thời gian phát triển của các lớp.`],
 ['Ứng dụng hôm nay: dự đoán cần biết đất và lịch sử nhiệt',`Nghiên cứu năm 2014 thực hiện các phép đông quá độ trên đất bùn bão hòa rồi xây mô hình đối chiếu với dữ liệu. Những mô hình khác xem việc xuất hiện lớp băng mới như quá trình mở một khuyết tật chứa băng trong vùng siêu lạnh. Các cách tiếp cận tạo những dự đoán có thể được thử về khoảng cách và tốc độ đội.

Kiến thức này hỗ trợ nghiên cứu nền đất và các vật liệu xốp khi đông, nhưng một bài giải thích nguyên lý không thay thiết kế địa kỹ thuật cho một công trình cụ thể. Nguồn nước và điều kiện biên thực tế cần được khảo sát.

Câu chuyện frost heave làm rõ rằng chuyển pha có thể tổ chức dòng vật chất. Băng không chỉ đóng tại chỗ rồi nằm yên; vùng phát triển có thể tiếp tục nhận nước, thay cấu trúc và tạo lực lên môi trường. Hiểu đường đi ấy giúp tránh một lời giải thích quá gọn và mở cách kết nối những tương tác ở giao diện với biến dạng lớn của đất.`],
 ],sources:[['Peppin và Style · Vật lý frost heave, 2013','https://doi.org/10.2136/vzj2012.0049'],['Nghiên cứu gốc · Thí nghiệm và mô hình thấu kính băng, 2014','https://www.sciencedirect.com/science/article/pii/S0165232X14000974'],['Nghiên cứu mô hình · Tạo thấu kính băng','https://arxiv.org/abs/1109.2000']]
},

{
 id:'eutectic-han-khong-chi-nong-chay-thap',category:'khainiem',title:'Mối hàn cần một giản đồ pha, không chỉ một nhiệt độ thấp',summary:'Nghiên cứu solder không chì dùng các hệ tin–silver–copper để cân bằng gia công và độ bền. Thành phần eutectic là một mốc hữu ích, không phải bảo đảm mọi tính năng.',tags:['Eutectic','Solder','Hợp kim','Giao diện'],image:'/assets/library/photos/elements/Sn.jpg',imageAlt:'Tin minh họa nguyên tố nền; không phải mẫu hợp kim solder cụ thể',sections:[
 ['Một vật liệu quen phải tìm đối tác thay thế',`Năm 1999, NEMI lập nhóm công tác để hỗ trợ công nghiệp điện tử phát triển sản phẩm không chì. Tài liệu NIST ghi những khuyến nghị hợp kim khác nhau cho các kiểu hàn, trong đó hệ tin–silver–copper và các lựa chọn tin–copper được xem xét theo yêu cầu sản xuất.

Bài toán không thể giải bằng cách bỏ chì rồi giữ nguyên mọi điều kiện. Nhiệt độ nóng chảy, khả năng thấm ướt, tạo pha và độ bền mỏi đều thay đổi. Một mối nối nhỏ phải sống qua nhiều lần nóng–nguội khi thiết bị hoạt động.

Nghiên cứu năm 2000 về eutectic ba thành phần Sn–Ag–Cu giúp xác định các quan hệ pha, cung cấp nền để chọn thành phần và hiểu quá trình đông đặc.`],
 ['Eutectic là một quan hệ giữa pha và thành phần',`Ở thành phần và điều kiện eutectic phù hợp, một pha lỏng chuyển thành tổ hợp pha rắn theo một nhiệt độ đặc trưng trong giản đồ. Gần điểm đó, phạm vi đông đặc có thể khác với hợp kim nằm xa hơn. Tuy nhiên, những sản phẩm thương mại thường được lựa chọn không chỉ để đúng một điểm nhiệt động lý tưởng.

Kích thước và phân bố các pha sau đông đặc ảnh hưởng cơ tính. Tốc độ làm nguội và các bề mặt tiếp xúc tạo cấu trúc thực, nên cùng thành phần danh nghĩa có thể cho vi cấu trúc khác.

Trong mối hàn trên copper, các hợp chất liên kim có thể hình thành ở giao diện. Một lớp thích hợp là phần của liên kết luyện kim, nhưng sự phát triển quá mức hoặc hình thái bất lợi có thể ảnh hưởng độ bền. Mối nối vì thế không chỉ là một giọt hợp kim nằm giữa hai vật trơ.`],
 ['Ứng dụng hôm nay: vật liệu cần được thử trong cấu hình mối nối',`Các công trình NIST về độ tin cậy và phát triển liên kim đặt ứng xử hợp kim cạnh loại linh kiện và tải nhiệt–cơ. Một thành phần tốt cho một quy trình không tự tối ưu cho mọi kích thước mối hàn hoặc môi trường.

Đánh giá còn phải xem sự lão hóa: vi cấu trúc có thể đổi trong quá trình sử dụng, làm tính chất ban đầu không còn nguyên. Phép thử gia tốc cần mô hình thích hợp để liên hệ với thời gian vận hành, thay vì chỉ báo mẫu chịu được một số chu kỳ.

Câu chuyện solder giúp giản đồ pha bước ra khỏi hình vẽ trong giáo trình. Những đường và vùng trên đó gợi phần nào của vật liệu sẽ xuất hiện, nhưng thiết bị thật còn có giao diện, hình học và lịch sử nhiệt. Một lựa chọn hợp kim có căn cứ phải nối cả ba, để mối hàn vừa được tạo dễ trong nhà máy vừa giữ công việc nối điện và cơ sau khi sản phẩm rời dây chuyền.`],
 ],sources:[['NIST · Khuyến nghị solder không chì của NEMI','https://www.nist.gov/publications/nemi-group-recommends-standardized-lead-free-solder-alternative'],['NIST · Eutectic ba thành phần Sn–Ag–Cu, 2000','https://www.nist.gov/publications/ternary-eutectic-sn-ag-cu-solder-alloys'],['NIST · Liên kim giữa solder không chì và copper','https://www.nist.gov/publications/formation-and-growth-intermetallics-interface-between-lead-free-solders-and-copper']]
},
{
 id:'kim-loai-thuy-tinh-giu-nguyen-tu-khong-kip-xep',category:'khainiem',title:'Kim loại có thể rắn lại mà chưa kịp tạo mạng tinh thể',summary:'Từ hợp kim gold–silicon năm 1960 tới thủy tinh kim loại khối, thiết kế thành phần giúp trì hoãn kết tinh. Trạng thái vô định hình tạo tính chất mới nhưng cũng có giới hạn cơ học.',tags:['Thủy tinh kim loại','Vô định hình','Kết tinh','Hợp kim'],image:'/assets/library/element-transition.svg',imageAlt:'Minh họa nhóm kim loại; không phải cấu trúc nguyên tử của hợp kim thủy tinh',sections:[
 ['Một hợp kim rắn không cho trật tự xa quen thuộc',`Năm 1960, Klement, Willens và Duwez báo cáo cấu trúc không tinh thể trong hợp kim gold–silicon được làm nguội nhanh. Kết quả mở câu hỏi về cách giữ một sắp xếp mất trật tự tương tự chất lỏng khi vật liệu đã trở thành rắn.

Những mẫu đầu đòi hỏi làm nguội rất nhanh, hạn chế kích thước. Về sau, nghiên cứu hướng tới hợp kim có khả năng tạo thủy tinh cao hơn để sản phẩm có thể dày hơn mà phần trong không kết tinh trước khi nguội.

Công việc của Peker tại Caltech trong hệ Zr–Ti–Cu–Ni–Be là một bước của hành trình ấy. Thành phần nhiều nguyên tố tạo thêm lựa chọn cho việc cân bằng trạng thái lỏng và các pha tinh thể cạnh tranh.`],
 ['Không có trật tự xa không có nghĩa nguyên tử hoàn toàn ngẫu nhiên',`Thủy tinh kim loại vẫn có các khoảng cách và phối trí cục bộ ưu tiên. Điều thiếu là một mạng tuần hoàn kéo dài như trong tinh thể thông thường. Khi nhiệt độ giảm đủ nhanh hoặc kết tinh bị trì hoãn, hệ có thể bị giữ trong trạng thái không cân bằng này.

Khả năng tạo thủy tinh phụ thuộc vào động học tạo mầm và phát triển, không chỉ chênh lệch năng lượng cuối. Kích thước nguyên tử, tương tác hóa học và những pha có thể hình thành đều tham gia. Không có một công thức đơn giản rằng càng trộn nhiều nguyên tố càng tốt.

Khi gia nhiệt, vật liệu có thể mềm trong miền chất lỏng siêu nguội hoặc kết tinh. Khoảng nhiệt và thời gian cho gia công phải được xác định, vì một thao tác quá lâu có thể làm mất cấu trúc vô định hình mong muốn.`],
 ['Ứng dụng hôm nay: chế tạo khối cần đi cùng kiểm soát biến dạng',`Thủy tinh kim loại được nghiên cứu cho các chi tiết có độ bền, đàn hồi và khả năng đúc tinh phù hợp. Tuy nhiên, biến dạng dẻo có thể tập trung trong những dải trượt hẹp, tạo giới hạn về độ dai ở một số cấu hình. Vật liệu composite có pha thứ hai là một hướng nhằm điều chỉnh hành vi đó.

Tổng kết lịch sử năm 2013 phân biệt sự phát triển của thủy tinh kim loại khối và các composite liên quan. Một đặc tính tốt của mẫu nhỏ chưa tự dự đoán độ bền của chi tiết lớn có khuyết tật và tải phức tạp.

Câu chuyện gold–silicon cho thấy rắn và tinh thể không phải hai từ đồng nghĩa. Bằng cách điều khiển thời gian mà nguyên tử có để sắp xếp, nhà nghiên cứu tạo được một trạng thái vật liệu khác. Thành công ứng dụng tiếp tục phụ thuộc vào việc giữ trạng thái ấy qua gia công và sử dụng, đồng thời hiểu những cách nó có thể biến dạng hoặc trở về các pha bền hơn.`],
 ],sources:[['Klement, Willens và Duwez · Hợp kim gold–silicon, 1960','https://www.nature.com/articles/187869b0'],['Peker · Nghiên cứu thủy tinh kim loại khối','https://thesis.library.caltech.edu/4245/1/Peker_a_1994.pdf'],['Tổng kết phát triển thủy tinh kim loại và composite','https://onlinelibrary.wiley.com/doi/full/10.1155/2013/517904']]
},
{
 id:'nitinol-nho-hinh-dang-bang-chuyen-pha',category:'khainiem',title:'Dây kim loại nhớ hình dạng vì mạng tinh thể đổi cách tổ chức',summary:'NiTi có thể phục hồi hình qua chuyển pha martensite–austenite. Lốp siêu đàn hồi của NASA khai thác một chế độ khác với việc chỉ nung dây đã uốn.',tags:['NiTi','Nhớ hình','Siêu đàn hồi','Chuyển pha'],image:'/assets/library/element-transition.svg',imageAlt:'Minh họa kim loại; không phải cấu trúc pha hoặc lốp NiTi của NASA',sections:[
 ['Một hợp kim được nghiên cứu như bộ truyền động',`Các báo cáo NASA thập niên 1970 mô tả việc dùng 55-Nitinol, hợp kim nickel–titanium phát triển từ công việc của Buehler và Wiley, để tạo chuyển động khi nhiệt độ thay đổi. Một chi tiết đã biến dạng có thể trở về hình được thiết lập trước khi đi qua miền chuyển pha phù hợp.

Điều này không phải kim loại nhớ bằng một chương trình điện tử. Cấu trúc tinh thể và những biến thể bên trong cho phép một dạng biến dạng được đảo khi điều kiện thay đổi.

Nhiệt độ chuyển không cố định cho mọi thứ mang tên Nitinol. Thành phần, xử lý và tải cơ học ảnh hưởng miền hoạt động, nên một thiết kế phải dùng dữ liệu của đúng vật liệu đã chế tạo.`],
 ['Nhớ hình và siêu đàn hồi có liên quan nhưng không giống nhau',`Ở chế độ nhớ hình thông thường, martensite có thể tái định hướng dưới tải; khi gia nhiệt chuyển sang austenite, hình dạng có thể được phục hồi. Đây khác với kéo dài đàn hồi rất nhỏ của kim loại thông thường và cũng khác biến dạng dẻo không hồi phục do trượt.

Trong chế độ siêu đàn hồi thích hợp, ứng suất có thể tạo chuyển pha rồi pha trở lại khi bỏ tải ở cùng vùng nhiệt độ. Vì vậy, không phải mọi lần phục hồi đều cần bật nguồn nhiệt ngoài sau mỗi thao tác.

Độ trễ giữa các chiều chuyển và mỏi qua chu kỳ là những giới hạn thực. Một mẫu phục hồi đẹp trong một lần trình diễn chưa chứng minh nó lặp được dưới mọi tải. Các phép đo nhiệt và cơ giúp xác định miền mà chức năng còn ổn định.`],
 ['Ứng dụng hôm nay: lựa chọn chế độ cho đúng công việc',`NASA Glenn phát triển lốp không khí nén dùng các thành phần chịu tải từ hợp kim nhớ hình, chủ yếu NiTi và dẫn xuất. Mục tiêu là biến dạng lớn rồi phục hồi, hỗ trợ thích nghi với bề mặt mà không để lại biến dạng dẻo quá mức như một số vật liệu truyền thống.

Cấu trúc lốp, liên kết giữa các phần và môi trường nhiệt quyết định hiệu năng tổng thể. Công bố công nghệ không có nghĩa mọi hợp kim NiTi đều phù hợp để thay cùng một loại lốp, hoặc mọi thiết kế đã được kiểm chứng cho mọi địa hình.

Câu chuyện từ bộ truyền động tới bánh xe cho thấy cùng một họ vật liệu có thể khai thác những miền khác nhau của giản đồ pha–ứng suất–nhiệt độ. Hóa học hợp kim tạo khả năng chuyển đổi, còn kỹ thuật chọn đường đi qua các trạng thái. Một dây kim loại trở thành phần tử chức năng khi sự thay đổi cấu trúc bên trong được nối với một chuyển động cần thiết bên ngoài.`],
 ],sources:[['NASA · 55-Nitinol và bộ phận nhớ hình','https://ntrs.nasa.gov/api/citations/19760012098/downloads/19760012098.pdf'],['NASA Glenn · Công nghệ lốp siêu đàn hồi','https://technology.nasa.gov/patent/LEW-TOPS-99']]
},
{
 id:'magnetocaloric-tu-truong-doi-nhiet-do',category:'khainiem',title:'Một từ trường có thể làm vật liệu đổi nhiệt độ',summary:'Hiệu ứng từ nhiệt khai thác sự thay đổi trật tự từ và entropy. Hợp kim Gd–Si–Ge cho thấy chuyển pha cấu trúc có thể khuếch đại đáp ứng.',tags:['Từ nhiệt','Entropy','Chuyển pha','Làm lạnh'],image:'/assets/library/photos/elements/Gd.jpg',imageAlt:'Gadolinium minh họa nguyên tố; nghiên cứu dùng hợp kim Gd₅Si₂Ge₂',sections:[
 ['Một hiệu ứng lớn được tìm trong họ hợp kim',`Năm 1997, Pecharsky và Gschneidner báo cáo biến đổi entropy từ rất lớn trong Gd₅Si₂Ge₂ gần nhiệt độ phòng. Công trình đặt vật liệu vào bối cảnh tìm môi chất cho làm lạnh bằng từ trường, như một hướng khác với chu trình nén–giãn khí quen thuộc.

Kết quả là đặc tính của hợp kim và miền chuyển pha cụ thể, không phải việc một khối gadolinium bất kỳ tạo lạnh miễn phí. Để chuyển nhiệt từ nơi lạnh sang nơi nóng vẫn cần một chu trình và công cung cấp từ bên ngoài.

Sự hấp dẫn nằm ở việc dùng một chất rắn đổi trạng thái có thể điều khiển, rồi phối hợp các bước trao đổi nhiệt theo nhịp ấy.`],
 ['Trật tự của spin chia sẻ entropy với mạng',`Từ trường ảnh hưởng cách các mômen từ được tổ chức. Nếu thay trường trong điều kiện gần đoạn nhiệt, sự thay đổi phần entropy từ có thể đi cùng thay đổi nhiệt độ. Nếu giữ nhiệt độ không đổi, hệ có thể trao đổi nhiệt với môi trường.

Các bước này cần được sắp thành chu trình để tạo tác dụng làm lạnh hữu ích. Chỉ đo một lần mẫu ấm lên hoặc lạnh đi chưa cho biết năng suất thiết bị. Nhiệt dung, truyền nhiệt và độ trễ quyết định mức năng lượng có thể chuyển qua mỗi chu kỳ.

Nghiên cứu nhiễu xạ năm 2000 trên Gd₅Si₂Ge₂ cho thấy chuyển từ gắn với biến đổi cấu trúc và khoảng cách giữa các nhóm nguyên tử. Sự ghép từ–cấu trúc là một phần của đáp ứng lớn, nhưng cũng có thể mang theo độ trễ và những đánh đổi về tính đảo ngược.`],
 ['Ứng dụng hôm nay: vật liệu và chu trình phải được tối ưu cùng nhau',`Các tổng kết về làm lạnh từ xem xét nhiều họ vật liệu và kiến trúc trao đổi nhiệt. Một mức biến đổi entropy cao không tự làm môi chất tốt nhất nếu cần trường quá lớn, dẫn nhiệt kém hoặc suy giảm qua nhiều lần chuyển.

Tính chất phải được đo trong miền nhiệt độ mong muốn, với cách thay trường và điều kiện nhiệt rõ ràng. Những số liệu gián tiếp từ quan hệ nhiệt động cần được đối chiếu với đo nhiệt trực tiếp khi có thể, đặc biệt gần chuyển pha bậc một.

Câu chuyện hợp kim gadolinium làm entropy trở thành một đại lượng có việc cụ thể. Nó không chỉ là khái niệm “mất trật tự” chung chung; thay đổi trạng thái từ có thể được liên hệ với lượng nhiệt trao đổi. Công nghệ tiến lên khi phần thay đổi ấy được lặp lại nhanh, bền và hiệu quả trong một hệ thống thực, nơi vật liệu phải đưa nhiệt tới đúng nơi chứ không chỉ đổi nhiệt độ của chính mình.`],
 ],sources:[['Pecharsky và Gschneidner · Hiệu ứng từ nhiệt lớn, 1997','https://doi.org/10.1103/PhysRevLett.78.4494'],['Nghiên cứu gốc · Liên kết và chuyển pha từ–cấu trúc','https://doi.org/10.1103/PhysRevLett.84.4617'],['Tổng kết vật liệu làm lạnh từ','https://doi.org/10.1088/1361-6463/50/5/053002']]
},

{
 id:'electrocaloric-polymer-thay-trat-tu-bang-dien',category:'khainiem',title:'Điện trường làm đổi trật tự và nhiệt độ của một màng polymer',summary:'Hiệu ứng điện nhiệt trong polymer sắt điện mở hướng làm lạnh rắn. Một đáp ứng lớn của màng cần được chuyển thành chu trình có trao đổi nhiệt hữu ích.',tags:['Điện nhiệt','Sắt điện','Polymer','Làm lạnh'],image:polymer,imageAlt:'Minh họa polymer; không phải cấu trúc pha của màng điện nhiệt cụ thể',sections:[
 ['Một màng mỏng được đo như môi chất nhiệt',`Năm 2008, Neese và cộng sự báo cáo hiệu ứng điện nhiệt lớn trong các copolymer và terpolymer chứa vinylidene fluoride. Hệ được quan tâm vì có thể dùng điện trường để điều chỉnh trạng thái phân cực, tạo thay đổi entropy và nhiệt độ trong điều kiện thích hợp.

Một màng có đáp ứng nhiệt không phải chiếc tủ lạnh hoàn chỉnh. Nó cần các bước nhận và thải nhiệt, điện cực và cách tuần hoàn trạng thái. Công trình vật liệu mở một khả năng, còn năng suất làm lạnh của hệ là câu hỏi tiếp theo.

Nghiên cứu năm 2021 về entropy cấu dạng trong các terpolymer tiếp tục khảo sát vì sao một số thành phần có đáp ứng cao ở trường thấp hơn, cho thấy thiết kế chuỗi và pha vẫn là trọng tâm.`],
 ['Trường điện điều chỉnh những trạng thái có thể tiếp cận',`Trong vật liệu phân cực, điện trường thay đổi mức ưu tiên của các định hướng hoặc cấu dạng. Nếu quá trình gần đoạn nhiệt, thay đổi phần entropy liên quan có thể đi cùng thay đổi nhiệt độ; nếu nhiệt độ được giữ, vật liệu trao đổi nhiệt với môi trường.

Cơ chế cần được phân biệt với nhiệt Joule do dòng rò. Một mẫu ấm lên khi cấp điện chưa đủ chứng minh hiệu ứng điện nhiệt hữu ích. Đo tính đảo ngược và tổn hao giúp xác định năng lượng nào có thể được dùng trong chu trình.

Các phép suy từ quan hệ nhiệt động thường được dùng, nhưng cần kiểm giả định và đối chiếu đo trực tiếp khi có thể. Gần chuyển pha hoặc trong hệ có độ trễ, đường đi của trạng thái ảnh hưởng kết quả. Không thể chỉ lấy một đường phân cực rồi xem mọi bước đều thuận nghịch.`],
 ['Ứng dụng hôm nay: hiệu năng cần tính cả điện trường và độ bền',`Vật liệu điện nhiệt được nghiên cứu cho làm lạnh ở quy mô nhỏ và những cấu hình trao đổi nhiệt mới. Màng mỏng thuận lợi cho trường cao và truyền nhiệt nhanh, nhưng lượng vật chất ít có thể giới hạn nhiệt chuyển mỗi chu kỳ. Xếp lớp tạo thêm bài toán cách điện và tiếp xúc.

Một chỉ số thay nhiệt độ lớn cần đi cùng trường áp, dải nhiệt hoạt động, tổn hao và số chu kỳ giữ được tính năng. Những yếu tố ấy quyết định liệu vật liệu có tiến tới thiết bị hiệu quả hay chỉ là một phép đo hấp dẫn.

Câu chuyện polymer điện nhiệt cho thấy entropy có thể được điều khiển bằng nhiều loại trường, không chỉ nhiệt độ. Nhưng năng lượng không biến mất khỏi cân bằng. Điện trường tổ chức lại các trạng thái của vật liệu, còn kỹ thuật phải sắp xếp lúc nào mẫu tiếp xúc nguồn nóng hay lạnh. Sự phối hợp giữa cấu trúc phân tử và lịch trình trao đổi nhiệt mới tạo tác dụng làm lạnh có thể dùng.`],
 ],sources:[['Neese và cộng sự · Điện nhiệt trong polymer, 2008','https://doi.org/10.1126/science.1159655'],['Nghiên cứu gốc · Entropy cấu dạng và điện nhiệt, 2021','https://doi.org/10.1126/science.aba4022']]
},
{
 id:'barocaloric-tinh-the-deo-bi-nen-doi-nhiet',category:'khainiem',title:'Nén một tinh thể phân tử để điều khiển nhiệt',summary:'Neopentyl glycol có chuyển pha định hướng đi cùng biến đổi entropy lớn. Hiệu ứng áp nhiệt cho thấy áp suất có thể điều chỉnh những bậc tự do quay của phân tử.',tags:['Áp nhiệt','Tinh thể dẻo','Entropy','Neopentyl glycol'],image:'/assets/library/organic-alcohol.svg',imageAlt:'Minh họa hợp chất hữu cơ có nhóm alcohol; không phải cấu trúc pha của neopentyl glycol',sections:[
 ['Một chất rắn có phân tử quay theo nhiều cách',`Năm 2019, Lloveras và cộng sự báo cáo hiệu ứng áp nhiệt lớn trong tinh thể dẻo neopentyl glycol. Một công trình độc lập cùng năm của Li và cộng sự cũng khảo sát sự thay đổi entropy và nhiệt độ quanh chuyển pha của vật liệu. Các kết quả thu hút chú ý tới chất rắn phân tử cho làm lạnh điều khiển bằng áp suất.

Tên “tinh thể dẻo” ở đây có nghĩa chuyên môn: các tâm phân tử có trật tự vị trí nhưng một số bậc tự do định hướng có thể mất trật tự. Nó không đơn giản nói chất mềm giống nhựa.

Sự chuyển giữa các trạng thái định hướng tạo một nguồn entropy có thể điều chỉnh. Áp suất tác động vì các pha có thể tích và năng lượng tự do khác nhau.`],
 ['Thay áp suất làm dịch điều kiện chuyển pha',`Trong một chu trình phù hợp, tăng hoặc giảm áp suất có thể đưa vật liệu qua chuyển pha. Nếu gần đoạn nhiệt, nhiệt độ thay đổi; ở bước trao đổi nhiệt, mẫu có thể nhận hoặc nhả nhiệt. Như các hiệu ứng caloric khác, tác dụng hữu ích cần cả chu trình chứ không chỉ một lần nén.

Độ trễ giữa nén và nhả làm giảm phần thay đổi có thể khai thác thuận nghịch. Tốc độ chuyển, dẫn nhiệt và điều kiện áp suất cũng ảnh hưởng. Một biến đổi entropy rất lớn nhưng đòi hỏi hệ áp lực cồng kềnh hoặc khó lặp không tự là giải pháp tối ưu.

Vật liệu có thể thay đổi thể tích khi chuyển pha, nên cơ học của lớp chứa và tiếp xúc nhiệt là phần thiết kế. Không thể xem mẫu chỉ là một con số nhiệt động đặt trong máy lý tưởng.`],
 ['Ứng dụng hôm nay: mở một họ môi chất để kiểm tra',`Các nghiên cứu áp nhiệt tiếp tục khảo sát tinh thể phân tử và những cấu trúc có chuyển pha thích hợp. Neopentyl glycol là một trường hợp cho thấy chuyển động quay và trật tự định hướng có thể tạo đáp ứng lớn, nhưng không chứng minh mọi alcohol nhỏ có cùng tính năng.

Thiết bị cần được đánh giá về nhiệt chuyển mỗi chu kỳ, công cơ cung cấp, độ bền và khả năng điều khiển. Những thông số vật liệu đo ở một mẫu nhỏ phải đi cùng mô hình và thử nghiệm hệ thống khi tăng quy mô.

Câu chuyện này bổ sung một cách nhìn về chất rắn: có trật tự vị trí không nghĩa mọi phân tử bị khóa hoàn toàn. Một phần tự do định hướng có thể được bật hoặc tắt qua chuyển pha, và sự thay đổi ấy hiện thành nhiệt. Hóa học phân tử cung cấp các trạng thái, còn áp suất chọn mức ưu tiên của chúng. Khi các trạng thái ấy được nối trong một chu trình bền, chúng mới có cơ hội trở thành công nghệ chuyển nhiệt.`],
 ],sources:[['Lloveras và cộng sự · Áp nhiệt trong tinh thể dẻo, 2019','https://doi.org/10.1038/s41467-019-09730-9'],['Li và cộng sự · Hiệu ứng barocaloric của neopentyl glycol, 2019','https://doi.org/10.1038/s41586-019-1042-5']]
},
{
 id:'zr-w-o-nong-len-lai-co',category:'khainiem',title:'Một mạng oxide nóng lên mà thể tích lại giảm',summary:'Zirconium tungstate là ví dụ nổi bật của giãn nở nhiệt âm. Dao động và chuyển động phối hợp trong mạng giúp giải thích điều trực giác về liên kết dài ra chưa kể hết.',tags:['Giãn nở nhiệt âm','ZrW₂O₈','Dao động mạng'],image:'/assets/library/ionic-crystal.svg',imageAlt:'Minh họa mạng oxide; không phải cấu trúc ZrW₂O₈ chính xác',sections:[
 ['Một hành vi từng bị xem là bất tiện trở thành công cụ thiết kế',`Tính co nhiệt của zirconium tungstate đã được ghi nhận trước khi công trình năm 1996 của nhóm Sleight làm rõ phạm vi rộng và liên hệ cấu trúc. Vật liệu có thể giảm kích thước khi được gia nhiệt trong một miền lớn, trái với nhiều chất rắn quen thuộc.

Nghiên cứu về tạo đơn tinh thể năm 2000 cho thấy việc chế tạo cũng có khó khăn vì miền ổn định nhiệt động hẹp và khả năng phân hủy không thuận lợi. Một tính chất nổi bật không xóa các ràng buộc về cách làm và giữ mẫu.

Khi muốn tạo composite có giãn nở thấp, vật liệu co khi nóng là một ứng viên hấp dẫn để cân bằng thành phần giãn dương. Nhưng trước hết phải hiểu cơ chế và độ bền của nó.`],
 ['Liên kết có thể dài hơn mà các tâm vẫn tiến gần',`Trong một mạng mở, các nhóm phối trí có thể chuyển động phối hợp và những dao động ngang của cầu nối có thể làm khoảng cách giữa các tâm giảm. Bức tranh hình học đơn giản gợi cách toàn mạng co dù không cần mọi liên kết riêng đều ngắn lại khi nhiệt độ tăng.

Các nghiên cứu phonon và mô hình mạng cho thấy cần xét nhiều mode dao động, không chỉ một chuyển động duy nhất. Thành phần, khuyết tật và pha ảnh hưởng mức đóng góp. Cách nói mạng “gập lại” là hình dung hữu ích nhưng phải được đối chiếu với dữ liệu tán xạ và tính toán.

Tính đẳng hướng của pha lập phương giúp khác với một số vật liệu co theo một hướng và giãn theo hướng khác. Khi dùng mẫu đa tinh thể, sự khác biệt này có ý nghĩa cho ứng suất nội và đáp ứng khối.`],
 ['Ứng dụng hôm nay: bù giãn nở cần cả tương thích vật liệu',`ZrW₂O₈ và các vật liệu liên quan được nghiên cứu để điều chỉnh giãn nở của composite và các chi tiết cần ổn định kích thước. Trộn một chất co với một chất giãn không tự cho hệ có giãn nở bằng không theo phép cộng đơn giản; môđun, phân bố hạt và giao diện cùng quyết định.

Áp suất và độ ẩm có thể làm một số mạng mở đổi trạng thái, nên điều kiện sử dụng phải được kiểm tra. Một hệ số nhiệt tốt trong một miền không nên được kéo dài ra mọi nhiệt độ.

Câu chuyện zirconium tungstate nhắc rằng tính chất khối là kết quả của cách các đơn vị cấu trúc chuyển động cùng nhau. Trực giác “nóng thì nguyên tử xa nhau hơn” chỉ là khởi đầu. Khi mạng có những bậc tự do đặc biệt, nhiệt có thể tăng chuyển động theo cách làm toàn thể tích giảm. Hóa học vật liệu trở nên thú vị ở chỗ nó cho phép thiết kế những ngoại lệ có quy luật, rồi thử xem ngoại lệ ấy hữu ích trong công việc nào.`],
 ],sources:[['Tổng kết cơ chế giãn nở nhiệt âm','https://pmc.ncbi.nlm.nih.gov/articles/PMC5448970/'],['Nghiên cứu gốc · Phonon của ZrW₂O₈','https://www.nature.com/articles/24115'],['Nghiên cứu gốc · Tạo đơn tinh thể ZrW₂O₈','https://doi.org/10.1016/S0022-0248(99)00892-1']]
},
{
 id:'invar-thuoc-do-it-doi-theo-nhiet',category:'khainiem',title:'Một thanh hợp kim ít giãn đã thay đổi công việc đo chiều dài',summary:'Guillaume tìm thấy vùng thành phần iron–nickel có giãn nở rất thấp. Invar nhắc rằng ổn định nhiệt và ổn định kích thước theo thời gian là hai yêu cầu khác nhau.',tags:['Invar','Giãn nở','Đo lường','Hợp kim'],image:'/assets/library/element-transition.svg',imageAlt:'Minh họa kim loại chuyển tiếp; không phải mẫu Invar hoặc chuẩn chiều dài lịch sử',sections:[
 ['Một bất thường đáng mừng đối với người làm chuẩn',`Trong bài giảng Nobel năm 1920, Charles-Édouard Guillaume kể năm 1896 một thanh thép chứa khoảng 30% nickel tới cơ quan cân đo và cho độ giãn thấp đáng chú ý. Điều này dẫn ông khảo sát có hệ thống các thành phần iron–nickel, tìm vùng gần 36% nickel với giãn nở rất nhỏ quanh nhiệt độ thường.

Với đo lường, sai số nhiệt độ chuyển thành sai số chiều dài theo hệ số giãn nở. Một vật liệu ít giãn có thể giảm mức nhạy của dụng cụ với môi trường, nhưng cần biết đặc tính được giữ trong miền nào.

Guillaume cũng gặp những hợp kim đổi tính từ và thể tích sau làm lạnh. Những bất thường ấy hấp dẫn về vật lý nhưng không tự phù hợp làm chuẩn ổn định.`],
 ['Tính từ và mạng tinh thể cùng góp vào kích thước',`Giãn nở thấp của Invar không chỉ do một liên kết có thế năng đối xứng đơn giản. Nó liên quan đến các đóng góp từ trạng thái từ và cấu trúc điện tử của hợp kim, có thể bù một phần xu hướng giãn nhiệt thông thường trong miền thích hợp.

Thành phần và xử lý nhiệt ảnh hưởng đáp ứng. Những biến dạng còn lại sau gia công có thể thư giãn theo thời gian, nên hệ số giãn nhỏ chưa bảo đảm chiều dài không trôi. Một thanh cần được ổn định cho nhiệm vụ đo lường phải được xem xét cả lịch sử chế tạo.

Không nên gọi mọi hợp kim iron–nickel là Invar với cùng một hệ số. Có nhiều cấp và biến thể được thiết kế cho các miền nhiệt hoặc tính chất khác. Con số cần đi cùng khoảng nhiệt độ và tình trạng mẫu.`],
 ['Ứng dụng hôm nay: giảm một sai số mà không quên những sai số khác',`Hướng dẫn thiết kế của Berkeley Lab ghi Invar là lựa chọn quen trong các hệ quang và cơ khí cần giãn nở thấp, đồng thời nhấn mạnh khác biệt giữa hệ số nhiệt và độ ổn định kích thước lâu dài. Thiết kế còn phải xét trọng lượng, dẫn nhiệt và cách ghép với vật liệu khác.

Một chi tiết ít giãn được gắn cứng vào khung giãn nhiều vẫn có thể nhận ứng suất hoặc lệch hình. Hệ thống cần tính tương thích tổng thể, không chỉ chọn vật liệu có con số nhỏ nhất trong bảng.

Câu chuyện Invar cho thấy phát minh vật liệu có thể bắt đầu từ một phép đo bất thường trong công việc thường ngày. Giá trị đến khi sự bất thường được lập bản đồ theo thành phần và điều kiện, rồi chuyển thành dữ liệu thiết kế. Một chiếc thước ổn định không phải vật nằm ngoài quy luật nhiệt; nó là kết quả của những đóng góp vật lý được cân bằng đủ tốt trong miền mà người sử dụng cần đo.`],
 ],sources:[['Guillaume · Bài giảng Nobel về Invar và Elinvar','https://www.nobelprize.org/uploads/2018/06/guillaume-lecture.pdf'],['Berkeley Lab · Vật liệu cho hệ cơ khí chính xác','https://medsi.lbl.gov/engineering-design-guide/materials']]
},
];
